// --- 類型定義 (原 types.ts) ---

export type ActionName = keyof typeof POINT_TABLE;

export type OperationType = 'DELETE' | 'COPY' | 'TRANSFORM' | 'ADD' | 'DELETE_REMOVE' | 'TRANSFORM_TO_REMOVE';

export interface CharacterData {
  id: string;
  name: string;
  counts: Record<ActionName, number>;
}

export interface LogEntry {
    id: string;
    timestamp: number;
    actionType: string; // e.g. "數值變更", "刪除操作"
    description: string;
    details?: string;
}

// --- 常數與設定 (原 constants.ts) ---

export const OPERATION_LABELS: Record<OperationType, string> = {
    'DELETE': '移除',
    'COPY': '複製',
    'TRANSFORM': '轉化',
    'ADD': '獲得',
    'DELETE_REMOVE': '移除(複製卡)', // 語意調整
    'TRANSFORM_TO_REMOVE': '轉化(特殊)'
};

// 核心計分規則表 (根據 2025/11/15 新版規則更新)
export const POINT_TABLE = {
    // 1. 獲得中立卡牌 +20pt
    "中立卡": [20, 40, 60, 80, 100],

    // 2. 獲得禁忌卡 +20pt
    "禁忌卡": [20, 40, 60, 80, 100],

    // 3. 獲得怪物卡 (一般+20, 稀有+50, 傳說+80)
    "怪物卡_一般": [20, 40, 60, 80, 100],
    "怪物卡_稀有": [50, 100, 150, 200, 250],
    "怪物卡_傳說": [80, 160, 240, 320, 400],

    // 5. 神閃統一 +20pt
    "神閃": [20, 40, 60, 80, 100],

    // 6. 複製卡片: 前2張0，之後每張+40 (0, 0, 40, 80)。
    // 公式 getPointsForAction 處理大於5的情況會依據最後一階差值(40)累加，故定義到第5階即可。
    "複製卡片": [0, 0, 40, 80, 120],

    // 9. 移除起始卡 +20pt
    "移除起始卡": [20, 40, 60, 80, 100],

    // 9. 移除其他卡 +0pt (但需要記錄次數)
    "一般移除": [0, 0, 0, 0, 0],

    // 11. 重鑄/神之錘 +10pt
    "重鑄_神之錘": [10, 20, 30, 40, 50]
};

export const ACTION_NAMES = Object.keys(POINT_TABLE) as ActionName[];

export const MIN_TIER = 1;
export const MAX_TIER = 100;
export const INITIAL_TIER = 1;

const createInitialCharacterState = (id: string, name: string): CharacterData => {
    const counts = {} as Record<ActionName, number>;
    ACTION_NAMES.forEach(action => {
        counts[action] = 0;
    });
    return { id, name, counts };
};

export const getInitialCharactersData = (): CharacterData[] => [
    createInitialCharacterState('char1', '角色 1'),
    createInitialCharacterState('char2', '角色 2'),
    createInitialCharacterState('char3', '角色 3'),
];

import React, { useState, useEffect } from 'react';
import { ActionName, OperationType } from '../config';
import { useModalEffects } from '../hooks/useModalEffects';

interface ActionOperationModalProps {
    isOpen: boolean;
    onClose: () => void;
    operationType: OperationType | null;
    currentCounts: Record<ActionName, number>;
    onConfirm: (updates: { action: ActionName; delta: number }[], logDetail?: string) => void;
}

// Section Wrapper Component for visual distinction
const SectionWrapper: React.FC<{ title: string, children: React.ReactNode, borderColor?: string }> = ({ title, children, borderColor }) => (
    <div className="bg-gray-50 dark:bg-slate-700/30 p-4 rounded-xl border border-gray-100 dark:border-slate-700 space-y-3">
        <h4 className={`text-sm font-bold text-gray-800 dark:text-gray-200 border-l-4 ${borderColor || 'border-indigo-500'} pl-2 leading-tight`}>
            {title}
        </h4>
        {children}
    </div>
);

const ActionOperationModal: React.FC<ActionOperationModalProps> = ({ isOpen, onClose, operationType, currentCounts, onConfirm }) => {
    const [errorMessage, setErrorMessage] = useState<string | null>(null);
    useModalEffects(isOpen, onClose, 'action-operation-modal');

    useEffect(() => {
        if (isOpen) {
            setErrorMessage(null);
        }
    }, [isOpen]);

    if (!isOpen || !operationType) return null;

    const getTitle = () => {
        switch (operationType) {
            case 'DELETE': return '執行移除';
            case 'COPY': return '執行複製';
            case 'TRANSFORM': return '執行轉化';
            case 'ADD': return '獲得卡片 / 資源';
            default: return '';
        }
    };

    const getDescription = () => {
        switch (operationType) {
            case 'DELETE': return '選擇要移除的卡片類型。移除起始卡+20pt，移除其他卡不計分。移除複製卡會退回該次複製的分數。';
            case 'COPY': return '執行複製操作。首2張免費，之後每張+40pt (單一角色最多複製4次)。';
            case 'TRANSFORM': return '轉化視同「移除來源卡片」並「獲得一張中立卡」。請選擇來源卡片類型。';
            case 'ADD': return '新增卡片或特殊計分項目。所有卡片普閃不計分，神閃統一+20pt。';
            default: return '';
        }
    };

    // Helper to generate updates based on selection
    const getUpdates = (category: string): { action: ActionName; delta: number }[] => {

        // --- ADD 獲得 ---
        if (operationType === 'ADD') {
            switch (category) {
                case 'NEUTRAL': return [{ action: '中立卡', delta: 1 }];
                case 'TABOO': return [{ action: '禁忌卡', delta: 1 }];
                case 'REFORGE': return [{ action: '重鑄_神之錘', delta: 1 }];

                case 'MONSTER_NORMAL': return [{ action: '怪物卡_一般', delta: 1 }];
                case 'MONSTER_RARE': return [{ action: '怪物卡_稀有', delta: 1 }];
                case 'MONSTER_LEGEND': return [{ action: '怪物卡_傳說', delta: 1 }];

                case 'GOD_FLASH': return [{ action: '神閃', delta: 1 }];
                default: return [];
            }
        }

        // --- COPY 複製 ---
        if (operationType === 'COPY') {
            // 規則6/7: 增加複製卡片計數 (場上複製卡)
            return [{ action: '複製卡片', delta: 1 }];
        }

        // --- DELETE 移除 ---
        if (operationType === 'DELETE') {
            switch (category) {
                // 規則9: 移除起始卡 +20pt
                case 'REMOVE_STARTER': return [{ action: '移除起始卡', delta: 1 }];
                // 規則9: 移除其他卡 +0pt
                case 'REMOVE_OTHER': return [{ action: '一般移除', delta: 1 }];
                // 規則7: 複製卡被移除，分數退回 (即複製卡片數 -1)
                case 'REMOVE_COPY': return [{ action: '複製卡片', delta: -1 }];
                default: return [];
            }
        }

        // --- TRANSFORM 轉化 ---
        if (operationType === 'TRANSFORM') {
            // 規則8/10: 轉化 = 移除來源 + 獲得新卡 (通常是中立卡)
            // 這裡假設轉化結果都是獲得一張中立卡 (+20pt)

            const gainNeutral = { action: '中立卡' as ActionName, delta: 1 };

            switch (category) {
                // 來源：起始卡 (+移除起始卡, +中立卡)
                case 'SRC_STARTER': 
                    return [{ action: '移除起始卡', delta: 1 }, gainNeutral];

                // 來源：其他卡 (+一般移除, +中立卡)
                case 'SRC_OTHER': 
                    return [{ action: '一般移除', delta: 1 }, gainNeutral];

                // 來源：複製卡 (-複製卡片, +中立卡) -> 退複製分，加中立分
                case 'SRC_COPY': 
                    return [{ action: '複製卡片', delta: -1 }, gainNeutral];

                default: return [];
            }
        }

        return [];
    };

    const getLogDescription = (category: string): string => {
        switch (operationType) {
            case 'ADD':
                 switch (category) {
                    case 'NEUTRAL': return '獲得中立卡';
                    case 'TABOO': return '獲得禁忌卡';
                    case 'REFORGE': return '重鑄/神之錘';
                    case 'MONSTER_NORMAL': return '獲得怪物卡(一般)';
                    case 'MONSTER_RARE': return '獲得怪物卡(稀有)';
                    case 'MONSTER_LEGEND': return '獲得怪物卡(傳說)';
                    case 'GOD_FLASH': return '獲得神閃';
                    default: return '';
                }
            case 'COPY': return '複製卡片';
            case 'DELETE':
                switch(category) {
                     case 'REMOVE_STARTER': return '移除起始卡';
                     case 'REMOVE_OTHER': return '移除一般卡';
                     case 'REMOVE_COPY': return '移除複製卡';
                     default: return '';
                }
             case 'TRANSFORM':
                switch(category) {
                     case 'SRC_STARTER': return '轉化起始卡';
                     case 'SRC_OTHER': return '轉化一般卡';
                     case 'SRC_COPY': return '轉化複製卡';
                     default: return '';
                }
            default: return '';
        }
    };

    const handleSelection = (category: string) => {
        setErrorMessage(null);
        const updates = getUpdates(category);
        const logDetail = getLogDescription(category);

        // Validation Logic: Check for negative results
        const missingItems: string[] = [];
        updates.forEach(({ action, delta }) => {
            if (delta < 0) {
                const currentCount = currentCounts[action] || 0;
                if (currentCount + delta < 0) {
                    missingItems.push(action);
                }
            }
        });

        if (missingItems.length > 0) {
            setErrorMessage(`無法執行操作：您的「${missingItems.join('、')}」數量不足。`);
            return;
        }

        onConfirm(updates, logDetail);
        onClose();
    };

    // Style Constants
    const baseBtnClass = "w-full py-3 px-4 rounded-lg border font-semibold text-sm sm:text-base transition-all active:scale-95 shadow-sm flex flex-col items-center justify-center gap-1";

    const blueBtnClass = `${baseBtnClass} bg-blue-50 text-blue-700 border-blue-200 hover:bg-blue-100 dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-800/50 dark:hover:bg-blue-900/30`;
    const greenBtnClass = `${baseBtnClass} bg-emerald-50 text-emerald-700 border-emerald-200 hover:bg-emerald-100 dark:bg-emerald-900/20 dark:text-emerald-300 dark:border-emerald-800/50 dark:hover:bg-emerald-900/30`;
    const purpleBtnClass = `${baseBtnClass} bg-purple-50 text-purple-700 border-purple-200 hover:bg-purple-100 dark:bg-purple-900/20 dark:text-purple-300 dark:border-purple-800/50 dark:hover:bg-purple-900/30`;
    const amberBtnClass = `${baseBtnClass} bg-amber-50 text-amber-700 border-amber-200 hover:bg-amber-100 dark:bg-amber-900/20 dark:text-amber-300 dark:border-amber-800/50 dark:hover:bg-amber-900/30`;
    const redBtnClass = `${baseBtnClass} bg-red-50 text-red-700 border-red-200 hover:bg-red-100 dark:bg-red-900/20 dark:text-red-300 dark:border-red-800/50 dark:hover:bg-red-900/30`;
    const grayBtnClass = `${baseBtnClass} bg-gray-50 text-gray-700 border-gray-200 hover:bg-gray-100 dark:bg-slate-700/40 dark:text-gray-300 dark:border-slate-600 dark:hover:bg-slate-700/60`;

    // --- Content Renderers ---

    const renderAddContent = () => (
        <div className="space-y-4">
            <SectionWrapper title="基礎卡片" borderColor="border-emerald-500">
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('NEUTRAL')} className={greenBtnClass}>
                        <span>中立卡</span>
                        <span className="text-xs opacity-70 font-normal">+20pt</span>
                    </button>
                    <button onClick={() => handleSelection('TABOO')} className={purpleBtnClass}>
                        <span>禁忌卡</span>
                        <span className="text-xs opacity-70 font-normal">+20pt</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="怪物卡" borderColor="border-red-500">
                <div className="grid grid-cols-3 gap-3">
                    <button onClick={() => handleSelection('MONSTER_NORMAL')} className={redBtnClass}>
                        <span>一般</span>
                        <span className="text-xs opacity-70 font-normal">+20pt</span>
                    </button>
                    <button onClick={() => handleSelection('MONSTER_RARE')} className={redBtnClass}>
                        <span>稀有</span>
                        <span className="text-xs opacity-70 font-normal">+50pt</span>
                    </button>
                    <button onClick={() => handleSelection('MONSTER_LEGEND')} className={redBtnClass}>
                        <span>傳說</span>
                        <span className="text-xs opacity-70 font-normal">+80pt</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="特殊" borderColor="border-amber-500">
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('REFORGE')} className={blueBtnClass}>
                        <span>重鑄 / 神之錘</span>
                        <span className="text-xs opacity-70 font-normal">+10pt</span>
                    </button>
                    <button onClick={() => handleSelection('GOD_FLASH')} className={amberBtnClass}>
                        <span>獲得神閃</span>
                        <span className="text-xs opacity-70 font-normal">統一 +20pt</span>
                    </button>
                </div>
                <p className="text-xs text-gray-500 dark:text-gray-400 mt-2 px-1">
                    * 普閃不計分，請勿記錄。神閃適用於任何種類卡片。
                </p>
            </SectionWrapper>
        </div>
    );

    const renderCopyContent = () => (
        <SectionWrapper title="複製操作" borderColor="border-blue-500">
            <button onClick={() => handleSelection('DEFAULT')} className={blueBtnClass}>
                <span>複製一張卡片</span>
                <span className="text-xs opacity-70 font-normal">首2張免費，後續+40pt</span>
            </button>
            <p className="text-xs text-gray-500 dark:text-gray-400 mt-2 px-1">
                * 單一角色最多複製 4 次。若複製卡被移除，分數會退回。
            </p>
        </SectionWrapper>
    );

    const renderDeleteContent = () => (
        <SectionWrapper title="移除類別" borderColor="border-red-500">
            <div className="grid grid-cols-1 gap-3">
                <button onClick={() => handleSelection('REMOVE_STARTER')} className={redBtnClass}>
                    <span>移除起始卡</span>
                    <span className="text-xs opacity-70 font-normal">+20pt</span>
                </button>
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('REMOVE_OTHER')} className={grayBtnClass}>
                        <span>移除其他卡</span>
                        <span className="text-xs opacity-70 font-normal">+0pt (僅計次)</span>
                    </button>
                    <button onClick={() => handleSelection('REMOVE_COPY')} className={blueBtnClass}>
                        <span>移除複製卡</span>
                        <span className="text-xs opacity-70 font-normal">退回複製分</span>
                    </button>
                </div>
            </div>
             <p className="text-xs text-gray-500 dark:text-gray-400 mt-2 px-1">
                * 單一角色最多移除 5 次。
            </p>
        </SectionWrapper>
    );

    const renderTransformContent = () => (
        <SectionWrapper title="轉化來源" borderColor="border-purple-500">
            <p className="text-sm text-gray-600 dark:text-gray-400 mb-2">
                轉化 = 移除一張卡 + 獲得一張中立卡。請選擇被轉化(移除)的卡片：
            </p>
            <div className="grid grid-cols-1 gap-3">
                 <button onClick={() => handleSelection('SRC_STARTER')} className={purpleBtnClass}>
                    <span>轉化起始卡</span>
                    <span className="text-xs opacity-70 font-normal">移除起始(+20) + 獲得中立(+20)</span>
                </button>
                <button onClick={() => handleSelection('SRC_OTHER')} className={grayBtnClass}>
                    <span>轉化一般卡</span>
                    <span className="text-xs opacity-70 font-normal">移除一般(+0) + 獲得中立(+20)</span>
                </button>
                <button onClick={() => handleSelection('SRC_COPY')} className={blueBtnClass}>
                    <span>轉化複製卡</span>
                    <span className="text-xs opacity-70 font-normal">退回複製分 + 獲得中立(+20)</span>
                </button>
            </div>
        </SectionWrapper>
    );

    const renderContent = () => {
        switch (operationType) {
            case 'ADD': return renderAddContent();
            case 'COPY': return renderCopyContent();
            case 'DELETE': return renderDeleteContent();
            case 'TRANSFORM': return renderTransformContent();
            default: return null;
        }
    }

    return (
        <div 
            className="fixed inset-0 bg-black bg-opacity-60 dark:bg-opacity-80 flex justify-center items-center z-50 p-4 transition-opacity duration-300"
            onClick={onClose}
        >
            <div 
                id="action-operation-modal"
                className="bg-white dark:bg-slate-800 w-full max-w-md rounded-xl p-6 max-h-[90vh] overflow-y-auto transform transition-all duration-300 ease-out opacity-0 scale-95"
                onClick={(e) => e.stopPropagation()}
            >
                <div className="flex justify-between items-center mb-2">
                    <h3 className="text-xl font-bold text-gray-900 dark:text-gray-100">{getTitle()}</h3>
                    <button onClick={onClose} className="p-2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-200">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                        </svg>
                    </button>
                </div>

                <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">{getDescription()}</p>

                {errorMessage && (
                    <div className="mb-4 p-3 bg-red-100 border border-red-200 text-red-700 rounded-lg text-sm flex items-start animate-pulse">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2 flex-shrink-0" viewBox="0 0 20 20" fill="currentColor">
                            <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                        </svg>
                        <span>{errorMessage}</span>
                    </div>
                )}

                {renderContent()}

                <div className="mt-6 pt-4 border-t border-gray-100 dark:border-gray-700 text-center">
                     <button 
                        onClick={onClose}
                        className="text-sm text-gray-500 hover:text-gray-800 dark:text-gray-400 dark:hover:text-gray-200 transition-colors"
                    >
                        取消
                    </button>
                </div>
            </div>
        </div>
    );
};

export default ActionOperationModal;

import React, { useState } from 'react';
import { CharacterData, ActionName, OperationType, LogEntry } from '../config';
import ActionOperationModal from './ActionOperationModal';
import ManualAdjustmentModal from './ManualAdjustmentModal';

interface CharacterCardProps {
    character: CharacterData;
    totalScore: number;
    maxLimit: number;
    onCountChange: (charId: string, actionName: ActionName, count: number) => void;
    onBatchCountChange: (charId: string, updates: { action: ActionName, delta: number }[], opType?: OperationType, logDetail?: string) => void;
    onNameChange: (charId: string, name: string) => void;
    onResetCharacter: (charId: string, name: string) => void;
    actionOrder: ActionName[];
    quickActionOrder: OperationType[];
    isManualInputLocked: boolean;
    logs: LogEntry[];
}

const CharacterCard: React.FC<CharacterCardProps> = ({ character, totalScore, maxLimit, onCountChange, onBatchCountChange, onNameChange, onResetCharacter, actionOrder, quickActionOrder, isManualInputLocked, logs }) => {
    // 預設展開詳細資訊 (Changed from false to true)
    const [isExpanded, setIsExpanded] = useState(true);
    const [activeOperation, setActiveOperation] = useState<OperationType | null>(null);

    const isOverLimit = totalScore > maxLimit;
    const remaining = maxLimit - totalScore;
    const percentage = Math.min(100, (totalScore / maxLimit) * 100);

    const handleOperationClick = (type: OperationType) => {
        setActiveOperation(type);
    };

    const handleOperationConfirm = (updates: { action: ActionName; delta: number }[], logDetail?: string) => {
        if (activeOperation) {
            onBatchCountChange(character.id, updates, activeOperation, logDetail);
        }
    };

    // Helper for consistent button styling - Minimalist Theme
    const getActionButtonClass = () => {
        // Unified minimalist style: Neutral background with Indigo hover effects
        return "flex flex-col items-center justify-center p-3 rounded-xl border border-gray-200 dark:border-slate-600 bg-gray-50 dark:bg-slate-700/30 text-gray-700 dark:text-gray-300 transition-all duration-200 active:scale-95 shadow-sm hover:shadow-md hover:border-indigo-300 dark:hover:border-indigo-500 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 hover:text-indigo-700 dark:hover:text-indigo-300 h-[4.5rem] group";
    };

    const renderButton = (type: OperationType) => {
        const btnClass = getActionButtonClass();

        // 僅保留新版規則需要的四個主要操作
        switch (type) {
            case 'DELETE':
                return (
                    <button key="DELETE" onClick={() => handleOperationClick('DELETE')} className={btnClass}>
                        <span className="font-bold text-lg leading-tight">移除</span>
                        <span className="text-xs opacity-70 font-medium group-hover:opacity-100 transition-opacity">起始/一般/複製</span>
                    </button>
                );
            case 'COPY':
                return (
                    <button key="COPY" onClick={() => handleOperationClick('COPY')} className={btnClass}>
                        <span className="font-bold text-lg leading-tight">複製</span>
                        <span className="text-xs opacity-70 font-medium group-hover:opacity-100 transition-opacity">0, 0, 40, 80</span>
                    </button>
                );
            case 'TRANSFORM':
                return (
                    <button key="TRANSFORM" onClick={() => handleOperationClick('TRANSFORM')} className={btnClass}>
                        <span className="font-bold text-lg leading-tight">轉化</span>
                        <span className="text-xs opacity-70 font-medium group-hover:opacity-100 transition-opacity">移除並獲得中立</span>
                    </button>
                );
            case 'ADD':
                return (
                    <button key="ADD" onClick={() => handleOperationClick('ADD')} className={btnClass}>
                        <span className="font-bold text-lg leading-tight">獲得</span>
                        <span className="text-xs opacity-70 font-medium group-hover:opacity-100 transition-opacity">卡片 / 神閃 / 重鑄</span>
                    </button>
                );
            default:
                return null;
        }
    };

    return (
        <div className="card bg-white dark:bg-slate-800 p-4 sm:p-5 rounded-xl flex flex-col transition-colors duration-300 relative">
            {/* Header */}
            <div className="flex justify-between items-center mb-4 pb-2 border-b border-gray-200 dark:border-gray-700 gap-4">
                <input 
                    type="text" 
                    value={character.name}
                    onChange={(e) => onNameChange(character.id, e.target.value)}
                    placeholder="輸入角色名稱"
                    className="name-input text-xl sm:text-2xl font-bold text-gray-800 dark:text-gray-200 border-b-2 focus:border-indigo-500 w-full p-0 transition duration-150 bg-transparent"
                />
                <button type="button" onClick={() => onResetCharacter(character.id, character.name)}
                    className="px-3 py-1.5 text-xs sm:text-sm font-semibold text-white bg-red-500 dark:bg-red-600/80 rounded-lg hover:bg-red-600 dark:hover:bg-red-600 transition duration-150 active:scale-95 flex-shrink-0 shadow">
                    重置
                </button>
            </div>

            {/* Progress Bar Score Status */}
            <div className="mb-5 px-1">
                <div className="flex justify-between items-end mb-1.5">
                    <span className={`text-sm font-bold ${isOverLimit ? 'text-red-600 dark:text-red-400' : 'text-gray-700 dark:text-gray-200'}`}>
                        累計 <span className="text-base">{totalScore}</span> <span className="text-xs font-normal text-gray-500">pt</span>
                    </span>
                    <span className="text-xs font-medium">
                        {remaining >= 0 ? (
                            <span className="text-gray-500 dark:text-gray-400">剩餘 {remaining} pt</span>
                        ) : (
                            <span className="text-red-500 dark:text-red-400">超過 {Math.abs(remaining)} pt</span>
                        )}
                    </span>
                </div>
                <div className="w-full bg-gray-200 dark:bg-slate-900 rounded-full h-3 overflow-hidden shadow-inner">
                    <div
                        className={`h-full rounded-full transition-all duration-500 ease-out ${
                            isOverLimit
                                ? 'bg-red-500 dark:bg-red-500' // Over limit color
                                : 'bg-indigo-500 dark:bg-indigo-500' // Unified Theme Color
                        }`}
                        style={{ width: `${percentage}%` }}
                    />
                </div>
            </div>

            {/* Quick Actions - Dynamic Order */}
            <div className="grid grid-cols-2 gap-3 mb-4">
                {quickActionOrder.map(type => renderButton(type))}
            </div>

            {/* Manual Adjustment Toggle Button */}
            <div>
                <button 
                    onClick={() => setIsExpanded(!isExpanded)}
                    className={`flex items-center justify-center w-full py-3 px-4 text-sm font-semibold rounded-lg transition-all active:scale-95 ${
                        isExpanded 
                            ? 'bg-indigo-50 dark:bg-indigo-900/20 text-indigo-700 dark:text-indigo-300 ring-1 ring-indigo-200 dark:ring-indigo-700/50' 
                            : 'bg-gray-100 dark:bg-slate-700/50 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-slate-600'
                    }`}
                >
                    <svg 
                        xmlns="http://www.w3.org/2000/svg" 
                        className={`h-5 w-5 mr-2 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} 
                        fill="none" 
                        viewBox="0 0 24 24" 
                        stroke="currentColor"
                    >
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                    </svg>
                    <span>詳細數據 / 操作紀錄</span>
                    {isManualInputLocked && !isExpanded && (
                        <span className="ml-2 px-1.5 py-0.5 text-xs bg-amber-100 dark:bg-amber-900/50 text-amber-700 dark:text-amber-400 rounded">
                            已鎖定
                        </span>
                    )}
                </button>
            </div>

            {/* Collapsible Manual Adjustment Section */}
            <div className={`transition-all duration-300 ease-in-out overflow-hidden ${isExpanded ? 'max-h-[1200px] opacity-100 mt-4' : 'max-h-0 opacity-0 mt-0'}`}>
                <ManualAdjustmentModal
                    character={character}
                    actionOrder={actionOrder}
                    onCountChange={onCountChange}
                    isManualInputLocked={isManualInputLocked}
                    logs={logs}
                />
            </div>

            {/* Modals */}
            <ActionOperationModal 
                isOpen={!!activeOperation}
                operationType={activeOperation}
                currentCounts={character.counts}
                onClose={() => setActiveOperation(null)}
                onConfirm={handleOperationConfirm}
            />
        </div>
    );
};

export default CharacterCard;

import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { CharacterData, ActionName, POINT_TABLE, ACTION_NAMES, MIN_TIER, MAX_TIER, INITIAL_TIER, getInitialCharactersData, OperationType, LogEntry, OPERATION_LABELS } from './config';
import TierControlCard from './components/TierControlCard';
import CharacterCard from './components/CharacterCard';
import ConfirmationModal from './components/ConfirmationModal';
import SortOrderModal from './components/SortOrderModal';

// --- LocalStorage Logic ---
const SAVED_STATE_KEY = 'chaos-simulator-state';

const loadState = () => {
  try {
    const serializedState = localStorage.getItem(SAVED_STATE_KEY);
    if (serializedState === null) {
      return undefined;
    }
    return JSON.parse(serializedState);
  } catch (err) {
    console.error("讀取儲存資料時發生錯誤:", err);
    return undefined;
  }
};

const savedState = loadState();

// --- Helper Functions ---

const getPointsForAction = (actionName: ActionName, count: number): number => {
    const points = POINT_TABLE[actionName];
    if (!points) return 0;

    const validCount = count || 0;
    if (validCount <= 0) return 0;

    if (validCount <= 5) {
        return points[validCount - 1];
    } else {
        const costOfStep5 = points[4] - points[3];
        return points[4] + (validCount - 5) * costOfStep5;
    }
};

const calculateTotalScore = (character: CharacterData): number => {
    return ACTION_NAMES.reduce((total, name) => {
        return total + getPointsForAction(name, character.counts[name]);
    }, 0);
};

const calculateMaxLimit = (tier: number): number => {
    const base = 30;
    const perTierBonus = 10;
    const validTier = Math.max(MIN_TIER, tier || MIN_TIER);
    return base + (validTier - 1) * perTierBonus;
};

const DEFAULT_QUICK_ACTION_ORDER: OperationType[] = ['DELETE', 'COPY', 'TRANSFORM', 'ADD'];

// Helper to create initial logs
const getInitialLogs = (chars: CharacterData[]) => {
    const logs: Record<string, LogEntry[]> = {};
    chars.forEach(c => logs[c.id] = []);
    return logs;
};

const App: React.FC = () => {
    const [sharedTier, setSharedTier] = useState<number>(savedState?.sharedTier ?? INITIAL_TIER);
    const [charactersData, setCharactersData] = useState<CharacterData[]>(savedState?.charactersData ?? getInitialCharactersData());
    const [characterLogs, setCharacterLogs] = useState<Record<string, LogEntry[]>>(savedState?.characterLogs ?? getInitialLogs(getInitialCharactersData()));
    const [activeCharacterId, setActiveCharacterId] = useState<string>(savedState?.activeCharacterId ?? getInitialCharactersData()[0].id);
    const [isConfirmationEnabled, setIsConfirmationEnabled] = useState<boolean>(savedState?.isConfirmationEnabled ?? true);

    // Initialize Dark Mode
    const [isDarkMode, setIsDarkMode] = useState<boolean>(() => {
        if (savedState?.isDarkMode !== undefined) {
            return savedState.isDarkMode;
        }
        if (typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
            return true;
        }
        return false;
    });

    const [isManualInputLocked, setIsManualInputLocked] = useState<boolean>(savedState?.isManualInputLocked ?? true);

    // Robust initialization for actionOrder to handle updates or missing keys
    const [actionOrder, setActionOrder] = useState<ActionName[]>(() => {
        if (savedState?.actionOrder && Array.isArray(savedState.actionOrder)) {
            const saved = savedState.actionOrder;
            // 1. Filter: Keep only keys that still exist in current config
            const validSaved = saved.filter((name: string) => ACTION_NAMES.includes(name as ActionName));
            // 2. Merge: Add any new keys from config that are missing in saved state
            const missing = ACTION_NAMES.filter(name => !validSaved.includes(name));
            return [...validSaved, ...missing] as ActionName[];
        }
        return ACTION_NAMES;
    });

    const [quickActionOrder, setQuickActionOrder] = useState<OperationType[]>(() => {
        if (savedState?.quickActionOrder && Array.isArray(savedState.quickActionOrder)) {
            const saved = savedState.quickActionOrder;

            // 1. Force Filter: Strict match against allowed types for this version to clean up old buttons
            const allowedTypes: OperationType[] = ['DELETE', 'COPY', 'TRANSFORM', 'ADD'];
            const validSaved = saved.filter((op: string) => allowedTypes.includes(op as any));

            // 2. Return valid saved order if exists, otherwise default
            return validSaved.length > 0 ? validSaved as OperationType[] : DEFAULT_QUICK_ACTION_ORDER;
        }
        return DEFAULT_QUICK_ACTION_ORDER;
    });

    const [isSortModalOpen, setIsSortModalOpen] = useState(false);

    // --- Undo History State ---
    // Now includes characterLogs to keep logs in sync with undo
    // Removed sharedTier from history so undoing doesn't revert tier changes
    const [history, setHistory] = useState<{
        charactersData: CharacterData[];
        characterLogs: Record<string, LogEntry[]>;
    }[]>(savedState?.history ?? []);

    const [confirmationState, setConfirmationState] = useState<{
        isOpen: boolean;
        title: string;
        message: string;
        onConfirm: (() => void) | null;
    }>({ isOpen: false, title: '', message: '', onConfirm: null });

    // Effect for save state to localStorage
    useEffect(() => {
        try {
            const stateToSave = {
                sharedTier,
                charactersData,
                characterLogs,
                activeCharacterId,
                isConfirmationEnabled,
                isDarkMode,
                isManualInputLocked,
                actionOrder,
                quickActionOrder,
                history
            };
            const serializedState = JSON.stringify(stateToSave);
            localStorage.setItem(SAVED_STATE_KEY, serializedState);
        } catch (err) {
            console.error("儲存資料時發生錯誤:", err);
        }
    }, [sharedTier, charactersData, characterLogs, activeCharacterId, isConfirmationEnabled, isDarkMode, isManualInputLocked, actionOrder, quickActionOrder, history]);

    useEffect(() => {
        document.documentElement.classList.toggle('dark', isDarkMode);
    }, [isDarkMode]);

    // --- Undo Logic ---
    const saveHistory = useCallback(() => {
        setHistory(prev => {
            const snapshot = {
                charactersData: JSON.parse(JSON.stringify(charactersData)),
                characterLogs: JSON.parse(JSON.stringify(characterLogs))
            };
            const newHistory = [...prev, snapshot];
            if (newHistory.length > 50) {
                return newHistory.slice(newHistory.length - 50);
            }
            return newHistory;
        });
    }, [charactersData, characterLogs]);

    const handleUndo = useCallback(() => {
        setHistory(prev => {
            if (prev.length === 0) return prev;
            const newHistory = [...prev];
            const lastState = newHistory.pop();

            if (lastState) {
                setCharactersData(lastState.charactersData);
                // 如果是舊的歷史紀錄沒有 logs，則使用初始 logs (空陣列) 防止崩潰
                setCharacterLogs(lastState.characterLogs || getInitialLogs(lastState.charactersData));
                // sharedTier is no longer restored from history
            }

            return newHistory;
        });
    }, []);

    const handleTierChange = useCallback((newTier: number) => {
        // Do not save history for Tier changes
        const validatedTier = Math.max(MIN_TIER, Math.min(MAX_TIER, newTier));
        setSharedTier(validatedTier);
    }, []);

    const performResetAll = useCallback(() => {
        setHistory([]); // Clear history on reset

        setCharactersData(prevData =>
            prevData.map(char => {
                const initialCharData = getInitialCharactersData().find(c => c.id === char.id);
                return { 
                    ...char, 
                    counts: initialCharData ? { ...initialCharData.counts } : char.counts 
                };
            })
        );
        // Clear all logs
        setCharacterLogs(getInitialLogs(getInitialCharactersData()));
    }, []);

    const handleResetAll = useCallback(() => {
        if (isConfirmationEnabled) {
            setConfirmationState({
                isOpen: true,
                title: '確認全部重置',
                message: '您確定要重置所有角色的分數與操作紀錄嗎？(TIER 等級將保留) 此操作無法復原。',
                onConfirm: performResetAll,
            });
        } else {
            performResetAll();
        }
    }, [isConfirmationEnabled, performResetAll]);

    const performResetCharacter = useCallback((charId: string) => {
        setHistory([]); // Clear history

        setCharactersData(prevData =>
            prevData.map(char => {
                if (char.id !== charId) return char;
                const initialCharData = getInitialCharactersData().find(c => c.id === charId);
                return { ...char, counts: initialCharData ? { ...initialCharData.counts } : char.counts };
            })
        );
        // Clear specific log
        setCharacterLogs(prev => ({
            ...prev,
            [charId]: []
        }));
    }, []);

    const handleResetCharacter = useCallback((charId: string, charName: string) => {
        if (isConfirmationEnabled) {
             setConfirmationState({
                isOpen: true,
                title: `確認重置角色`,
                message: `您確定要重置角色「${charName}」的所有分數與操作紀錄嗎？此操作無法復原。`,
                onConfirm: () => performResetCharacter(charId),
            });
        } else {
            performResetCharacter(charId);
        }
    }, [isConfirmationEnabled, performResetCharacter]);

    // Helper to add log
    const addLog = useCallback((charId: string, actionType: string, description: string, details: string = "") => {
        const newLog: LogEntry = {
            id: Date.now().toString() + Math.random().toString(36).substr(2, 9),
            timestamp: Date.now(),
            actionType,
            description,
            details
        };
        setCharacterLogs(prev => ({
            ...prev,
            [charId]: [newLog, ...(prev[charId] || [])]
        }));
    }, []);

    const handleCountChange = useCallback((charId: string, actionName: ActionName, newCount: number) => {
        saveHistory();
        setCharactersData(prevData =>
            prevData.map(char => {
                if (char.id !== charId) return char;

                const currentCount = char.counts[actionName];
                const delta = newCount - currentCount;

                if (delta === 0) return char;

                const updatedCounts = { ...char.counts };
                updatedCounts[actionName] = Math.max(0, newCount);

                let logDescription = `${actionName} ${delta > 0 ? '+' : ''}${delta}`;
                let logDetails = `數值變更：${currentCount} ➔ ${newCount}`;

                addLog(charId, "手動調整", logDescription, logDetails);

                return { ...char, counts: updatedCounts };
            })
        );
    }, [saveHistory, addLog]);

    const handleBatchCountChange = useCallback((charId: string, updates: { action: ActionName, delta: number }[], opType?: OperationType, logDetail?: string) => {
        saveHistory();

        const opLabel = opType ? OPERATION_LABELS[opType] : "批量操作";

        let numericDesc = "";
        if (updates.length > 0) {
            numericDesc = updates.map(u => {
                if (u.delta === 0) return `${u.action} (不計)`;
                return `${u.action} ${u.delta > 0 ? '+' : ''}${u.delta}`;
            }).join("、");
        }

        let mainDesc = "";
        let details = "";

        if (numericDesc) {
            mainDesc = numericDesc;
            if (logDetail) {
                details = logDetail;
            }
        } else {
            // No numeric updates (e.g., DELETE_REMOVE or CHAR_TO_REMOVE)
            mainDesc = logDetail || "無數值變動";
        }

        // Ensure we don't log empty entries if for some reason both are empty, 
        // though UI interaction should prevent this.
        if (mainDesc || details) {
             addLog(charId, opLabel, mainDesc, details);
        }

        setCharactersData(prevData =>
            prevData.map(char => {
                if (char.id !== charId) return char;
                const updatedCounts = { ...char.counts };

                updates.forEach(({ action, delta }) => {
                    const current = updatedCounts[action] || 0;
                    updatedCounts[action] = Math.max(0, current + delta);
                });

                return { ...char, counts: updatedCounts };
            })
        );
    }, [saveHistory, addLog]);

    const handleNameChange = useCallback((charId: string, newName: string) => {
        saveHistory();
        setCharactersData(prevData =>
            prevData.map(char => (char.id === charId ? { ...char, name: newName } : char))
        );
    }, [saveHistory]);

    const handleSortOrderChange = useCallback((newActionOrder: ActionName[], newQuickActionOrder: OperationType[]) => {
        setActionOrder(newActionOrder);
        setQuickActionOrder(newQuickActionOrder);
        setIsSortModalOpen(false);
    }, []);

    const closeConfirmationModal = () => {
        setConfirmationState({ isOpen: false, title: '', message: '', onConfirm: null });
    };

    const handleConfirm = () => {
        if (confirmationState.onConfirm) {
            confirmationState.onConfirm();
        }
        closeConfirmationModal();
    };

    const maxLimit = useMemo(() => calculateMaxLimit(sharedTier), [sharedTier]);

    const characterScores = useMemo(() => {
        const scores: { [key: string]: number } = {};
        charactersData.forEach(char => {
            scores[char.id] = calculateTotalScore(char);
        });
        return scores;
    }, [charactersData]);

    return (
        <div className="container mx-auto max-w-7xl p-4 lg:p-8 min-h-screen flex flex-col pb-24">
            <h1 className="text-3xl font-extrabold text-gray-900 dark:text-gray-100 mb-6 text-center">
                卡厄思計分模擬器
            </h1>

            <TierControlCard 
                tier={sharedTier}
                maxLimit={maxLimit}
                onTierChange={handleTierChange}
                onResetAll={handleResetAll}
                isConfirmationEnabled={isConfirmationEnabled}
                onConfirmationToggle={() => setIsConfirmationEnabled(prev => !prev)}
                isDarkMode={isDarkMode}
                onThemeToggle={() => setIsDarkMode(prev => !prev)}
                onUndo={handleUndo}
                canUndo={history.length > 0}
                isManualInputLocked={isManualInputLocked}
                onToggleLock={() => setIsManualInputLocked(prev => !prev)}
                onOpenSort={() => setIsSortModalOpen(true)}
            />

            <div id="characters-container" className="flex-grow">
                {/* --- Tab view for smaller screens (< 960px) --- */}
                <div className="min-[960px]:hidden">
                    <div className="flex border-b border-gray-200 dark:border-gray-700 mb-4">
                        {charactersData.map(char => (
                            <button
                                key={char.id}
                                onClick={() => setActiveCharacterId(char.id)}
                                className={`px-4 py-2 font-semibold text-base transition-colors duration-200 w-1/3 text-center ${
                                    activeCharacterId === char.id
                                        ? 'border-b-2 border-indigo-500 text-indigo-600 bg-indigo-50 dark:bg-slate-800 dark:text-indigo-400 rounded-t-lg'
                                        : 'text-gray-500 dark:text-gray-400 hover:text-indigo-500 hover:bg-gray-100 dark:hover:bg-slate-800'
                                }`}
                            >
                                {char.name}
                            </button>
                        ))}
                    </div>
                    <div>
                        {charactersData
                            .filter(char => char.id === activeCharacterId)
                            .map(char => (
                                 <CharacterCard
                                    key={char.id}
                                    character={char}
                                    totalScore={characterScores[char.id]}
                                    maxLimit={maxLimit}
                                    onCountChange={handleCountChange}
                                    onBatchCountChange={handleBatchCountChange}
                                    onNameChange={handleNameChange}
                                    onResetCharacter={handleResetCharacter}
                                    actionOrder={actionOrder}
                                    quickActionOrder={quickActionOrder}
                                    isManualInputLocked={isManualInputLocked}
                                    logs={characterLogs[char.id] || []}
                                />
                            ))}
                    </div>
                </div>

                {/* --- Grid view for larger screens (>= 960px) --- */}
                <div className="hidden min-[960px]:grid min-[960px]:grid-cols-3 min-[960px]:gap-6 items-start">
                    {charactersData.map(char => (
                        <CharacterCard
                            key={char.id}
                            character={char}
                            totalScore={characterScores[char.id]}
                            maxLimit={maxLimit}
                            onCountChange={handleCountChange}
                            onBatchCountChange={handleBatchCountChange}
                            onNameChange={handleNameChange}
                            onResetCharacter={handleResetCharacter}
                            actionOrder={actionOrder}
                            quickActionOrder={quickActionOrder}
                            isManualInputLocked={isManualInputLocked}
                            logs={characterLogs[char.id] || []}
                        />
                    ))}
                </div>
            </div>

            <p className="text-xs text-gray-500 dark:text-gray-400 mt-6 text-center">
               根據巴友【恋姫】緋色飛翔者 所提供的<a href="https://forum.gamer.com.tw/Co.php?bsn=80099&sn=8886" target="_blank" rel="noopener noreferrer" className="text-indigo-600 hover:text-indigo-800 dark:text-indigo-400 dark:hover:text-indigo-300">試算表</a>製作而成
               <span className="mx-2">|</span>
               <span>v2.2.2</span>
            </p>

            <ConfirmationModal
                isOpen={confirmationState.isOpen}
                title={confirmationState.title}
                message={confirmationState.message}
                onClose={closeConfirmationModal}
                onConfirm={handleConfirm}
            />

            <SortOrderModal 
                isOpen={isSortModalOpen}
                currentActionOrder={actionOrder}
                currentQuickOrder={quickActionOrder}
                onClose={() => setIsSortModalOpen(false)}
                onSave={handleSortOrderChange}
            />
        </div>
    );
};

export default App;

import React, { useState, useEffect } from 'react';
import { ActionName, OperationType } from '../config';
import { useModalEffects } from '../hooks/useModalEffects';

interface ActionOperationModalProps {
    isOpen: boolean;
    onClose: () => void;
    operationType: OperationType | null;
    currentCounts: Record<ActionName, number>;
    onConfirm: (updates: { action: ActionName; delta: number }[], logDetail?: string) => void;
}

// Section Wrapper Component for visual distinction
const SectionWrapper: React.FC<{ title: string, children: React.ReactNode, borderColor?: string }> = ({ title, children, borderColor }) => (
    <div className="bg-gray-50 dark:bg-slate-700/30 p-4 rounded-xl border border-gray-100 dark:border-slate-700 space-y-3">
        <h4 className={`text-sm font-bold text-gray-800 dark:text-gray-200 border-l-4 ${borderColor || 'border-indigo-500'} pl-2 leading-tight`}>
            {title}
        </h4>
        {children}
    </div>
);

const ActionOperationModal: React.FC<ActionOperationModalProps> = ({ isOpen, onClose, operationType, currentCounts, onConfirm }) => {
    const [errorMessage, setErrorMessage] = useState<string | null>(null);
    useModalEffects(isOpen, onClose, 'action-operation-modal');

    useEffect(() => {
        if (isOpen) {
            setErrorMessage(null);
        }
    }, [isOpen]);

    if (!isOpen || !operationType) return null;

    const getTitle = () => {
        switch (operationType) {
            case 'DELETE': return '執行移除';
            case 'COPY': return '執行複製';
            case 'TRANSFORM': return '執行轉化';
            case 'ADD': return '獲得卡片 / 資源';
            default: return '';
        }
    };

    const getDescription = () => {
        switch (operationType) {
            case 'DELETE': return '選擇要移除的卡片類型。移除起始卡+20pt，移除其他卡不計分。移除複製卡會退回該次複製的分數。';
            case 'COPY': return '選擇複製對象。首2張免費，之後每張+40pt (單一角色最多複製4次)。若有神閃會自動+20pt。';
            case 'TRANSFORM': return '轉化視同「移除來源卡片」並「獲得一張中立卡」。請選擇來源卡片類型。';
            case 'ADD': return '新增卡片或特殊計分項目。所有卡片普閃不計分，神閃統一+20pt。';
            default: return '';
        }
    };

    // Helper to generate updates based on selection
    const getUpdates = (category: string): { action: ActionName; delta: number }[] => {

        // --- ADD 獲得 ---
        if (operationType === 'ADD') {
            switch (category) {
                case 'NEUTRAL': return [{ action: '中立卡', delta: 1 }];
                case 'TABOO': return [{ action: '禁忌卡', delta: 1 }];
                case 'REFORGE': return [{ action: '重鑄_神之錘', delta: 1 }];

                case 'MONSTER_NORMAL': return [{ action: '怪物卡_一般', delta: 1 }];
                case 'MONSTER_RARE': return [{ action: '怪物卡_稀有', delta: 1 }];
                case 'MONSTER_LEGEND': return [{ action: '怪物卡_傳說', delta: 1 }];

                case 'GOD_FLASH': return [{ action: '神閃', delta: 1 }];
                default: return [];
            }
        }

        // --- COPY 複製 ---
        if (operationType === 'COPY') {
            const baseCopy = { action: '複製卡片' as ActionName, delta: 1 };
            const godFlash = { action: '神閃' as ActionName, delta: 1 };

            switch (category) {
                // 角色卡
                case 'COPY_CHAR_NORMAL': return [baseCopy];
                case 'COPY_CHAR_GOD': return [baseCopy, godFlash];

                // 中立卡
                case 'COPY_NEUTRAL_NORMAL': return [baseCopy];
                case 'COPY_NEUTRAL_GOD': return [baseCopy, godFlash];

                // 怪物卡
                case 'COPY_MONSTER_NORMAL': return [baseCopy];
                case 'COPY_MONSTER_GOD': return [baseCopy, godFlash];

                default: return [baseCopy];
            }
        }

        // --- DELETE 移除 ---
        if (operationType === 'DELETE') {
            switch (category) {
                // 規則9: 移除起始卡 +20pt
                case 'REMOVE_STARTER': return [{ action: '移除起始卡', delta: 1 }];
                // 規則9: 移除其他卡 +0pt
                case 'REMOVE_OTHER': return [{ action: '一般移除', delta: 1 }];
                // 規則7: 複製卡被移除，分數退回 (即複製卡片數 -1)
                case 'REMOVE_COPY': return [{ action: '複製卡片', delta: -1 }];
                default: return [];
            }
        }

        // --- TRANSFORM 轉化 ---
        if (operationType === 'TRANSFORM') {
            // 規則8/10: 轉化 = 移除來源 + 獲得新卡 (通常是中立卡)
            // 這裡假設轉化結果都是獲得一張中立卡 (+20pt)

            const gainNeutral = { action: '中立卡' as ActionName, delta: 1 };

            switch (category) {
                // 來源：起始卡 (+移除起始卡, +中立卡)
                case 'SRC_STARTER': 
                    return [{ action: '移除起始卡', delta: 1 }, gainNeutral];

                // 來源：其他卡 (+一般移除, +中立卡)
                case 'SRC_OTHER': 
                    return [{ action: '一般移除', delta: 1 }, gainNeutral];

                // 來源：複製卡 (-複製卡片, +中立卡) -> 退複製分，加中立分
                case 'SRC_COPY': 
                    return [{ action: '複製卡片', delta: -1 }, gainNeutral];

                default: return [];
            }
        }

        return [];
    };

    const getLogDescription = (category: string): string => {
        switch (operationType) {
            case 'ADD':
                 switch (category) {
                    case 'NEUTRAL': return '獲得中立卡';
                    case 'TABOO': return '獲得禁忌卡';
                    case 'REFORGE': return '重鑄/神之錘';
                    case 'MONSTER_NORMAL': return '獲得怪物卡(一般)';
                    case 'MONSTER_RARE': return '獲得怪物卡(稀有)';
                    case 'MONSTER_LEGEND': return '獲得怪物卡(傳說)';
                    case 'GOD_FLASH': return '獲得神閃';
                    default: return '';
                }
            case 'COPY': 
                switch (category) {
                    case 'COPY_CHAR_NORMAL': return '複製角色卡';
                    case 'COPY_CHAR_GOD': return '複製角色卡(神閃)';
                    case 'COPY_NEUTRAL_NORMAL': return '複製中立卡';
                    case 'COPY_NEUTRAL_GOD': return '複製中立卡(神閃)';
                    case 'COPY_MONSTER_NORMAL': return '複製怪物卡';
                    case 'COPY_MONSTER_GOD': return '複製怪物卡(神閃)';
                    default: return '複製卡片';
                }
            case 'DELETE':
                switch(category) {
                     case 'REMOVE_STARTER': return '移除起始卡';
                     case 'REMOVE_OTHER': return '移除一般卡';
                     case 'REMOVE_COPY': return '移除複製卡';
                     default: return '';
                }
             case 'TRANSFORM':
                switch(category) {
                     case 'SRC_STARTER': return '轉化起始卡';
                     case 'SRC_OTHER': return '轉化一般卡';
                     case 'SRC_COPY': return '轉化複製卡';
                     default: return '';
                }
            default: return '';
        }
    };

    const handleSelection = (category: string) => {
        setErrorMessage(null);
        const updates = getUpdates(category);
        const logDetail = getLogDescription(category);

        // Validation Logic: Check for negative results
        const missingItems: string[] = [];
        updates.forEach(({ action, delta }) => {
            if (delta < 0) {
                const currentCount = currentCounts[action] || 0;
                if (currentCount + delta < 0) {
                    missingItems.push(action);
                }
            }
        });

        if (missingItems.length > 0) {
            setErrorMessage(`無法執行操作：您的「${missingItems.join('、')}」數量不足。`);
            return;
        }

        onConfirm(updates, logDetail);
        onClose();
    };

    // Style Constants
    const baseBtnClass = "w-full py-3 px-4 rounded-lg border font-semibold text-sm sm:text-base transition-all active:scale-95 shadow-sm flex flex-col items-center justify-center gap-1";

    const blueBtnClass = `${baseBtnClass} bg-blue-50 text-blue-700 border-blue-200 hover:bg-blue-100 dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-800/50 dark:hover:bg-blue-900/30`;
    const greenBtnClass = `${baseBtnClass} bg-emerald-50 text-emerald-700 border-emerald-200 hover:bg-emerald-100 dark:bg-emerald-900/20 dark:text-emerald-300 dark:border-emerald-800/50 dark:hover:bg-emerald-900/30`;
    const purpleBtnClass = `${baseBtnClass} bg-purple-50 text-purple-700 border-purple-200 hover:bg-purple-100 dark:bg-purple-900/20 dark:text-purple-300 dark:border-purple-800/50 dark:hover:bg-purple-900/30`;
    const amberBtnClass = `${baseBtnClass} bg-amber-50 text-amber-700 border-amber-200 hover:bg-amber-100 dark:bg-amber-900/20 dark:text-amber-300 dark:border-amber-800/50 dark:hover:bg-amber-900/30`;
    const redBtnClass = `${baseBtnClass} bg-red-50 text-red-700 border-red-200 hover:bg-red-100 dark:bg-red-900/20 dark:text-red-300 dark:border-red-800/50 dark:hover:bg-red-900/30`;
    const grayBtnClass = `${baseBtnClass} bg-gray-50 text-gray-700 border-gray-200 hover:bg-gray-100 dark:bg-slate-700/40 dark:text-gray-300 dark:border-slate-600 dark:hover:bg-slate-700/60`;

    // --- Content Renderers ---

    const renderAddContent = () => (
        <div className="space-y-4">
            <SectionWrapper title="基礎卡片" borderColor="border-emerald-500">
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('NEUTRAL')} className={greenBtnClass}>
                        <span>中立卡</span>
                        <span className="text-xs opacity-70 font-normal">+20pt</span>
                    </button>
                    <button onClick={() => handleSelection('TABOO')} className={purpleBtnClass}>
                        <span>禁忌卡</span>
                        <span className="text-xs opacity-70 font-normal">+20pt</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="怪物卡" borderColor="border-red-500">
                <div className="grid grid-cols-3 gap-3">
                    <button onClick={() => handleSelection('MONSTER_NORMAL')} className={redBtnClass}>
                        <span>一般</span>
                        <span className="text-xs opacity-70 font-normal">+20pt</span>
                    </button>
                    <button onClick={() => handleSelection('MONSTER_RARE')} className={redBtnClass}>
                        <span>稀有</span>
                        <span className="text-xs opacity-70 font-normal">+50pt</span>
                    </button>
                    <button onClick={() => handleSelection('MONSTER_LEGEND')} className={redBtnClass}>
                        <span>傳說</span>
                        <span className="text-xs opacity-70 font-normal">+80pt</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="特殊" borderColor="border-amber-500">
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('REFORGE')} className={blueBtnClass}>
                        <span>重鑄 / 神之錘</span>
                        <span className="text-xs opacity-70 font-normal">+10pt</span>
                    </button>
                    <button onClick={() => handleSelection('GOD_FLASH')} className={amberBtnClass}>
                        <span>獲得神閃</span>
                        <span className="text-xs opacity-70 font-normal">統一 +20pt</span>
                    </button>
                </div>
                <p className="text-xs text-gray-500 dark:text-gray-400 mt-2 px-1">
                    * 普閃不計分，請勿記錄。神閃適用於任何種類卡片。
                </p>
            </SectionWrapper>
        </div>
    );

    const renderCopyContent = () => (
        <div className="space-y-4">
            <SectionWrapper title="複製角色卡 (Character)" borderColor="border-blue-500">
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('COPY_CHAR_NORMAL')} className={blueBtnClass}>
                        <span>非神閃</span>
                        <span className="text-xs opacity-70 font-normal">複製+1</span>
                    </button>
                    <button onClick={() => handleSelection('COPY_CHAR_GOD')} className={amberBtnClass}>
                        <span>神閃</span>
                        <span className="text-xs opacity-70 font-normal">複製+1 / 神閃+1</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="複製中立卡 (Neutral)" borderColor="border-green-500">
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('COPY_NEUTRAL_NORMAL')} className={blueBtnClass}>
                        <span>非神閃</span>
                        <span className="text-xs opacity-70 font-normal">複製+1</span>
                    </button>
                    <button onClick={() => handleSelection('COPY_NEUTRAL_GOD')} className={amberBtnClass}>
                        <span>神閃</span>
                        <span className="text-xs opacity-70 font-normal">複製+1 / 神閃+1</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="複製怪物卡 (Monster)" borderColor="border-red-500">
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('COPY_MONSTER_NORMAL')} className={blueBtnClass}>
                        <span>非神閃</span>
                        <span className="text-xs opacity-70 font-normal">複製+1</span>
                    </button>
                    <button onClick={() => handleSelection('COPY_MONSTER_GOD')} className={amberBtnClass}>
                        <span>神閃</span>
                        <span className="text-xs opacity-70 font-normal">複製+1 / 神閃+1</span>
                    </button>
                </div>
            </SectionWrapper>
        </div>
    );

    const renderDeleteContent = () => (
        <SectionWrapper title="移除類別" borderColor="border-red-500">
            <div className="grid grid-cols-1 gap-3">
                <button onClick={() => handleSelection('REMOVE_STARTER')} className={redBtnClass}>
                    <span>移除起始卡</span>
                    <span className="text-xs opacity-70 font-normal">+20pt</span>
                </button>
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('REMOVE_OTHER')} className={grayBtnClass}>
                        <span>移除其他卡</span>
                        <span className="text-xs opacity-70 font-normal">+0pt (僅計次)</span>
                    </button>
                    <button onClick={() => handleSelection('REMOVE_COPY')} className={blueBtnClass}>
                        <span>移除複製卡</span>
                        <span className="text-xs opacity-70 font-normal">退回複製分</span>
                    </button>
                </div>
            </div>
             <p className="text-xs text-gray-500 dark:text-gray-400 mt-2 px-1">
                * 單一角色最多移除 5 次。
            </p>
        </SectionWrapper>
    );

    const renderTransformContent = () => (
        <SectionWrapper title="轉化來源" borderColor="border-purple-500">
            <p className="text-sm text-gray-600 dark:text-gray-400 mb-2">
                轉化 = 移除一張卡 + 獲得一張中立卡。請選擇被轉化(移除)的卡片：
            </p>
            <div className="grid grid-cols-1 gap-3">
                 <button onClick={() => handleSelection('SRC_STARTER')} className={purpleBtnClass}>
                    <span>轉化起始卡</span>
                    <span className="text-xs opacity-70 font-normal">移除起始(+20) + 獲得中立(+20)</span>
                </button>
                <button onClick={() => handleSelection('SRC_OTHER')} className={grayBtnClass}>
                    <span>轉化一般卡</span>
                    <span className="text-xs opacity-70 font-normal">移除一般(+0) + 獲得中立(+20)</span>
                </button>
                <button onClick={() => handleSelection('SRC_COPY')} className={blueBtnClass}>
                    <span>轉化複製卡</span>
                    <span className="text-xs opacity-70 font-normal">退回複製分 + 獲得中立(+20)</span>
                </button>
            </div>
        </SectionWrapper>
    );

    const renderContent = () => {
        switch (operationType) {
            case 'ADD': return renderAddContent();
            case 'COPY': return renderCopyContent();
            case 'DELETE': return renderDeleteContent();
            case 'TRANSFORM': return renderTransformContent();
            default: return null;
        }
    }

    return (
        <div 
            className="fixed inset-0 bg-black bg-opacity-60 dark:bg-opacity-80 flex justify-center items-center z-50 p-4 transition-opacity duration-300"
            onClick={onClose}
        >
            <div 
                id="action-operation-modal"
                className="bg-white dark:bg-slate-800 w-full max-w-md rounded-xl p-6 max-h-[90vh] overflow-y-auto transform transition-all duration-300 ease-out opacity-0 scale-95"
                onClick={(e) => e.stopPropagation()}
            >
                <div className="flex justify-between items-center mb-2">
                    <h3 className="text-xl font-bold text-gray-900 dark:text-gray-100">{getTitle()}</h3>
                    <button onClick={onClose} className="p-2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-200">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                        </svg>
                    </button>
                </div>

                <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">{getDescription()}</p>

                {errorMessage && (
                    <div className="mb-4 p-3 bg-red-100 border border-red-200 text-red-700 rounded-lg text-sm flex items-start animate-pulse">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2 flex-shrink-0" viewBox="0 0 20 20" fill="currentColor">
                            <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                        </svg>
                        <span>{errorMessage}</span>
                    </div>
                )}

                {renderContent()}

                <div className="mt-6 pt-4 border-t border-gray-100 dark:border-gray-700 text-center">
                     <button 
                        onClick={onClose}
                        className="text-sm text-gray-500 hover:text-gray-800 dark:text-gray-400 dark:hover:text-gray-200 transition-colors"
                    >
                        取消
                    </button>
                </div>
            </div>
        </div>
    );
};

export default ActionOperationModal;

import React, { useState, useEffect } from 'react';
import { ActionName, OperationType } from '../config';
import { useModalEffects } from '../hooks/useModalEffects';

interface ActionOperationModalProps {
    isOpen: boolean;
    onClose: () => void;
    operationType: OperationType | null;
    currentCounts: Record<ActionName, number>;
    onConfirm: (updates: { action: ActionName; delta: number }[], logDetail?: string) => void;
}

// Section Wrapper Component for visual distinction
const SectionWrapper: React.FC<{ title: string, children: React.ReactNode, borderColor?: string }> = ({ title, children, borderColor }) => (
    <div className="bg-gray-50 dark:bg-slate-700/30 p-4 rounded-xl border border-gray-100 dark:border-slate-700 space-y-3">
        <h4 className={`text-sm font-bold text-gray-800 dark:text-gray-200 border-l-4 ${borderColor || 'border-indigo-500'} pl-2 leading-tight`}>
            {title}
        </h4>
        {children}
    </div>
);

const ActionOperationModal: React.FC<ActionOperationModalProps> = ({ isOpen, onClose, operationType, currentCounts, onConfirm }) => {
    const [errorMessage, setErrorMessage] = useState<string | null>(null);
    useModalEffects(isOpen, onClose, 'action-operation-modal');

    useEffect(() => {
        if (isOpen) {
            setErrorMessage(null);
        }
    }, [isOpen]);

    if (!isOpen || !operationType) return null;

    const getTitle = () => {
        switch (operationType) {
            case 'DELETE': return '執行移除';
            case 'COPY': return '執行複製';
            case 'TRANSFORM': return '執行轉化';
            case 'ADD': return '獲得卡片 / 資源';
            default: return '';
        }
    };

    const getDescription = () => {
        switch (operationType) {
            case 'DELETE': return '選擇要移除的卡片類型。移除起始卡+20pt，移除其他卡不計分（僅計次）。若移除神閃卡片，會扣除神閃點數。';
            case 'COPY': return '選擇複製對象。首2張免費，之後每張+40pt (單一角色最多複製4次)。若有神閃會自動+20pt。';
            case 'TRANSFORM': return '轉化視同「移除來源卡片」並「獲得一張中立卡」。請選擇來源卡片類型。';
            case 'ADD': return '新增卡片或特殊計分項目。所有卡片普閃不計分，神閃統一+20pt。';
            default: return '';
        }
    };

    // Helper to generate updates based on selection
    const getUpdates = (category: string): { action: ActionName; delta: number }[] => {

        // --- ADD 獲得 ---
        if (operationType === 'ADD') {
            switch (category) {
                case 'NEUTRAL': return [{ action: '中立卡', delta: 1 }];
                case 'TABOO': return [{ action: '禁忌卡', delta: 1 }];
                case 'REFORGE': return [{ action: '重鑄_神之錘', delta: 1 }];

                case 'MONSTER_NORMAL': return [{ action: '怪物卡_一般', delta: 1 }];
                case 'MONSTER_RARE': return [{ action: '怪物卡_稀有', delta: 1 }];
                case 'MONSTER_LEGEND': return [{ action: '怪物卡_傳說', delta: 1 }];

                case 'GOD_FLASH': return [{ action: '神閃', delta: 1 }];
                default: return [];
            }
        }

        // --- COPY 複製 ---
        if (operationType === 'COPY') {
            const baseCopy = { action: '複製卡片' as ActionName, delta: 1 };
            const godFlash = { action: '神閃' as ActionName, delta: 1 };

            switch (category) {
                // 角色卡
                case 'COPY_CHAR_NORMAL': return [baseCopy];
                case 'COPY_CHAR_GOD': return [baseCopy, godFlash];

                // 中立卡
                case 'COPY_NEUTRAL_NORMAL': return [baseCopy];
                case 'COPY_NEUTRAL_GOD': return [baseCopy, godFlash];

                // 怪物卡
                case 'COPY_MONSTER_NORMAL': return [baseCopy];
                case 'COPY_MONSTER_GOD': return [baseCopy, godFlash];

                default: return [baseCopy];
            }
        }

        // --- DELETE 移除 ---
        if (operationType === 'DELETE') {
            const removeCommon = { action: '一般移除' as ActionName, delta: 1 };
            const removeGodFlash = { action: '神閃' as ActionName, delta: -1 };

            switch (category) {
                // 1. 角色卡
                case 'DEL_CHAR_STARTER': 
                    return [{ action: '移除起始卡', delta: 1 }];
                case 'DEL_CHAR_GOD': 
                    return [removeCommon, removeGodFlash];
                case 'DEL_CHAR_NORMAL': 
                    return [removeCommon];

                // 2. 中立卡
                case 'DEL_NEUTRAL_NORMAL':
                    return [removeCommon];
                case 'DEL_NEUTRAL_GOD':
                    return [removeCommon, removeGodFlash];

                // 3. 怪物卡
                case 'DEL_MONSTER_NORMAL':
                    return [removeCommon];
                case 'DEL_MONSTER_GOD':
                    return [removeCommon, removeGodFlash];

                // 4. 禁忌卡
                case 'DEL_TABOO':
                    return [removeCommon];

                // 特殊：移除複製卡 (維持原邏輯，退回複製分)
                case 'REMOVE_COPY': 
                    return [{ action: '複製卡片', delta: -1 }];

                default: return [];
            }
        }

        // --- TRANSFORM 轉化 ---
        if (operationType === 'TRANSFORM') {
            // 規則8/10: 轉化 = 移除來源 + 獲得新卡 (通常是中立卡)

            const gainNeutral = { action: '中立卡' as ActionName, delta: 1 };

            switch (category) {
                // 來源：起始卡 (+移除起始卡, +中立卡)
                case 'SRC_STARTER': 
                    return [{ action: '移除起始卡', delta: 1 }, gainNeutral];

                // 來源：其他卡 (+一般移除, +中立卡)
                case 'SRC_OTHER': 
                    return [{ action: '一般移除', delta: 1 }, gainNeutral];

                // 來源：複製卡 (-複製卡片, +中立卡) -> 退複製分，加中立分
                case 'SRC_COPY': 
                    return [{ action: '複製卡片', delta: -1 }, gainNeutral];

                default: return [];
            }
        }

        return [];
    };

    const getLogDescription = (category: string): string => {
        switch (operationType) {
            case 'ADD':
                 switch (category) {
                    case 'NEUTRAL': return '獲得中立卡';
                    case 'TABOO': return '獲得禁忌卡';
                    case 'REFORGE': return '重鑄/神之錘';
                    case 'MONSTER_NORMAL': return '獲得怪物卡(一般)';
                    case 'MONSTER_RARE': return '獲得怪物卡(稀有)';
                    case 'MONSTER_LEGEND': return '獲得怪物卡(傳說)';
                    case 'GOD_FLASH': return '獲得神閃';
                    default: return '';
                }
            case 'COPY': 
                switch (category) {
                    case 'COPY_CHAR_NORMAL': return '複製角色卡';
                    case 'COPY_CHAR_GOD': return '複製角色卡(神閃)';
                    case 'COPY_NEUTRAL_NORMAL': return '複製中立卡';
                    case 'COPY_NEUTRAL_GOD': return '複製中立卡(神閃)';
                    case 'COPY_MONSTER_NORMAL': return '複製怪物卡';
                    case 'COPY_MONSTER_GOD': return '複製怪物卡(神閃)';
                    default: return '複製卡片';
                }
            case 'DELETE':
                switch(category) {
                     case 'DEL_CHAR_STARTER': return '移除起始卡';
                     case 'DEL_CHAR_GOD': return '移除角色卡(神閃)';
                     case 'DEL_CHAR_NORMAL': return '移除角色卡(一般)';
                     case 'DEL_NEUTRAL_NORMAL': return '移除中立卡(一般)';
                     case 'DEL_NEUTRAL_GOD': return '移除中立卡(神閃)';
                     case 'DEL_MONSTER_NORMAL': return '移除怪物卡(一般)';
                     case 'DEL_MONSTER_GOD': return '移除怪物卡(神閃)';
                     case 'DEL_TABOO': return '移除禁忌卡';
                     case 'REMOVE_COPY': return '移除複製卡';
                     default: return '移除卡片';
                }
             case 'TRANSFORM':
                switch(category) {
                     case 'SRC_STARTER': return '轉化起始卡';
                     case 'SRC_OTHER': return '轉化一般卡';
                     case 'SRC_COPY': return '轉化複製卡';
                     default: return '';
                }
            default: return '';
        }
    };

    const handleSelection = (category: string) => {
        setErrorMessage(null);
        const updates = getUpdates(category);
        const logDetail = getLogDescription(category);

        // Validation Logic: Check for negative results
        const missingItems: string[] = [];
        updates.forEach(({ action, delta }) => {
            if (delta < 0) {
                const currentCount = currentCounts[action] || 0;
                if (currentCount + delta < 0) {
                    missingItems.push(action);
                }
            }
        });

        if (missingItems.length > 0) {
            setErrorMessage(`無法執行操作：您的「${missingItems.join('、')}」數量不足。`);
            return;
        }

        onConfirm(updates, logDetail);
        onClose();
    };

    // Style Constants
    const baseBtnClass = "w-full py-3 px-4 rounded-lg border font-semibold text-sm sm:text-base transition-all active:scale-95 shadow-sm flex flex-col items-center justify-center gap-1";

    const blueBtnClass = `${baseBtnClass} bg-blue-50 text-blue-700 border-blue-200 hover:bg-blue-100 dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-800/50 dark:hover:bg-blue-900/30`;
    const greenBtnClass = `${baseBtnClass} bg-emerald-50 text-emerald-700 border-emerald-200 hover:bg-emerald-100 dark:bg-emerald-900/20 dark:text-emerald-300 dark:border-emerald-800/50 dark:hover:bg-emerald-900/30`;
    const purpleBtnClass = `${baseBtnClass} bg-purple-50 text-purple-700 border-purple-200 hover:bg-purple-100 dark:bg-purple-900/20 dark:text-purple-300 dark:border-purple-800/50 dark:hover:bg-purple-900/30`;
    const amberBtnClass = `${baseBtnClass} bg-amber-50 text-amber-700 border-amber-200 hover:bg-amber-100 dark:bg-amber-900/20 dark:text-amber-300 dark:border-amber-800/50 dark:hover:bg-amber-900/30`;
    const redBtnClass = `${baseBtnClass} bg-red-50 text-red-700 border-red-200 hover:bg-red-100 dark:bg-red-900/20 dark:text-red-300 dark:border-red-800/50 dark:hover:bg-red-900/30`;
    const grayBtnClass = `${baseBtnClass} bg-gray-50 text-gray-700 border-gray-200 hover:bg-gray-100 dark:bg-slate-700/40 dark:text-gray-300 dark:border-slate-600 dark:hover:bg-slate-700/60`;

    // --- Content Renderers ---

    const renderAddContent = () => (
        <div className="space-y-4">
            <SectionWrapper title="基礎卡片" borderColor="border-emerald-500">
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('NEUTRAL')} className={greenBtnClass}>
                        <span>中立卡</span>
                        <span className="text-xs opacity-70 font-normal">+20pt</span>
                    </button>
                    <button onClick={() => handleSelection('TABOO')} className={purpleBtnClass}>
                        <span>禁忌卡</span>
                        <span className="text-xs opacity-70 font-normal">+20pt</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="怪物卡" borderColor="border-red-500">
                <div className="grid grid-cols-3 gap-3">
                    <button onClick={() => handleSelection('MONSTER_NORMAL')} className={redBtnClass}>
                        <span>一般</span>
                        <span className="text-xs opacity-70 font-normal">+20pt</span>
                    </button>
                    <button onClick={() => handleSelection('MONSTER_RARE')} className={redBtnClass}>
                        <span>稀有</span>
                        <span className="text-xs opacity-70 font-normal">+50pt</span>
                    </button>
                    <button onClick={() => handleSelection('MONSTER_LEGEND')} className={redBtnClass}>
                        <span>傳說</span>
                        <span className="text-xs opacity-70 font-normal">+80pt</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="特殊" borderColor="border-amber-500">
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('REFORGE')} className={blueBtnClass}>
                        <span>重鑄 / 神之錘</span>
                        <span className="text-xs opacity-70 font-normal">+10pt</span>
                    </button>
                    <button onClick={() => handleSelection('GOD_FLASH')} className={amberBtnClass}>
                        <span>獲得神閃</span>
                        <span className="text-xs opacity-70 font-normal">統一 +20pt</span>
                    </button>
                </div>
                <p className="text-xs text-gray-500 dark:text-gray-400 mt-2 px-1">
                    * 普閃不計分，請勿記錄。神閃適用於任何種類卡片。
                </p>
            </SectionWrapper>
        </div>
    );

    const renderCopyContent = () => (
        <div className="space-y-4">
            <SectionWrapper title="複製角色卡 (Character)" borderColor="border-blue-500">
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('COPY_CHAR_NORMAL')} className={blueBtnClass}>
                        <span>非神閃</span>
                        <span className="text-xs opacity-70 font-normal">複製+1</span>
                    </button>
                    <button onClick={() => handleSelection('COPY_CHAR_GOD')} className={amberBtnClass}>
                        <span>神閃</span>
                        <span className="text-xs opacity-70 font-normal">複製+1 / 神閃+1</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="複製中立卡 (Neutral)" borderColor="border-green-500">
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('COPY_NEUTRAL_NORMAL')} className={blueBtnClass}>
                        <span>非神閃</span>
                        <span className="text-xs opacity-70 font-normal">複製+1</span>
                    </button>
                    <button onClick={() => handleSelection('COPY_NEUTRAL_GOD')} className={amberBtnClass}>
                        <span>神閃</span>
                        <span className="text-xs opacity-70 font-normal">複製+1 / 神閃+1</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="複製怪物卡 (Monster)" borderColor="border-red-500">
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('COPY_MONSTER_NORMAL')} className={blueBtnClass}>
                        <span>非神閃</span>
                        <span className="text-xs opacity-70 font-normal">複製+1</span>
                    </button>
                    <button onClick={() => handleSelection('COPY_MONSTER_GOD')} className={amberBtnClass}>
                        <span>神閃</span>
                        <span className="text-xs opacity-70 font-normal">複製+1 / 神閃+1</span>
                    </button>
                </div>
            </SectionWrapper>
        </div>
    );

    const renderDeleteContent = () => (
        <div className="space-y-4">
            <SectionWrapper title="1. 角色卡 (Character)" borderColor="border-blue-500">
                <div className="grid grid-cols-3 gap-2">
                    <button onClick={() => handleSelection('DEL_CHAR_STARTER')} className={redBtnClass}>
                        <span>起始卡</span>
                        <span className="text-xs opacity-70 font-normal">+20pt</span>
                    </button>
                    <button onClick={() => handleSelection('DEL_CHAR_GOD')} className={amberBtnClass}>
                        <span>神閃</span>
                        <span className="text-xs opacity-70 font-normal">移除+1 / 神閃-1</span>
                    </button>
                    <button onClick={() => handleSelection('DEL_CHAR_NORMAL')} className={grayBtnClass}>
                        <span>非起始</span>
                        <span className="text-xs opacity-70 font-normal">移除+1</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="2. 中立卡 (Neutral)" borderColor="border-green-500">
                 <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('DEL_NEUTRAL_NORMAL')} className={grayBtnClass}>
                        <span>一般 / 普閃</span>
                        <span className="text-xs opacity-70 font-normal">移除+1</span>
                    </button>
                    <button onClick={() => handleSelection('DEL_NEUTRAL_GOD')} className={amberBtnClass}>
                        <span>神閃</span>
                        <span className="text-xs opacity-70 font-normal">移除+1 / 神閃-1</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="3. 怪物卡 (Monster)" borderColor="border-red-500">
                <div className="grid grid-cols-2 gap-3">
                     <button onClick={() => handleSelection('DEL_MONSTER_NORMAL')} className={grayBtnClass}>
                        <span>一般 / 普閃</span>
                        <span className="text-xs opacity-70 font-normal">移除+1</span>
                    </button>
                    <button onClick={() => handleSelection('DEL_MONSTER_GOD')} className={amberBtnClass}>
                        <span>神閃</span>
                        <span className="text-xs opacity-70 font-normal">移除+1 / 神閃-1</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="4. 其他 (Other)" borderColor="border-gray-500">
                <div className="grid grid-cols-2 gap-3">
                     <button onClick={() => handleSelection('DEL_TABOO')} className={purpleBtnClass}>
                        <span>禁忌卡</span>
                        <span className="text-xs opacity-70 font-normal">移除+1</span>
                    </button>
                    <button onClick={() => handleSelection('REMOVE_COPY')} className={blueBtnClass}>
                        <span>複製卡</span>
                        <span className="text-xs opacity-70 font-normal">退回複製分</span>
                    </button>
                </div>
            </SectionWrapper>
        </div>
    );

    const renderTransformContent = () => (
        <SectionWrapper title="轉化來源" borderColor="border-purple-500">
            <p className="text-sm text-gray-600 dark:text-gray-400 mb-2">
                轉化 = 移除一張卡 + 獲得一張中立卡。請選擇被轉化(移除)的卡片：
            </p>
            <div className="grid grid-cols-1 gap-3">
                 <button onClick={() => handleSelection('SRC_STARTER')} className={purpleBtnClass}>
                    <span>轉化起始卡</span>
                    <span className="text-xs opacity-70 font-normal">移除起始(+20) + 獲得中立(+20)</span>
                </button>
                <button onClick={() => handleSelection('SRC_OTHER')} className={grayBtnClass}>
                    <span>轉化一般卡</span>
                    <span className="text-xs opacity-70 font-normal">移除一般(+0) + 獲得中立(+20)</span>
                </button>
                <button onClick={() => handleSelection('SRC_COPY')} className={blueBtnClass}>
                    <span>轉化複製卡</span>
                    <span className="text-xs opacity-70 font-normal">退回複製分 + 獲得中立(+20)</span>
                </button>
            </div>
        </SectionWrapper>
    );

    const renderContent = () => {
        switch (operationType) {
            case 'ADD': return renderAddContent();
            case 'COPY': return renderCopyContent();
            case 'DELETE': return renderDeleteContent();
            case 'TRANSFORM': return renderTransformContent();
            default: return null;
        }
    }

    return (
        <div 
            className="fixed inset-0 bg-black bg-opacity-60 dark:bg-opacity-80 flex justify-center items-center z-50 p-4 transition-opacity duration-300"
            onClick={onClose}
        >
            <div 
                id="action-operation-modal"
                className="bg-white dark:bg-slate-800 w-full max-w-md rounded-xl p-6 max-h-[90vh] overflow-y-auto transform transition-all duration-300 ease-out opacity-0 scale-95"
                onClick={(e) => e.stopPropagation()}
            >
                <div className="flex justify-between items-center mb-2">
                    <h3 className="text-xl font-bold text-gray-900 dark:text-gray-100">{getTitle()}</h3>
                    <button onClick={onClose} className="p-2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-200">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                        </svg>
                    </button>
                </div>

                <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">{getDescription()}</p>

                {errorMessage && (
                    <div className="mb-4 p-3 bg-red-100 border border-red-200 text-red-700 rounded-lg text-sm flex items-start animate-pulse">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2 flex-shrink-0" viewBox="0 0 20 20" fill="currentColor">
                            <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                        </svg>
                        <span>{errorMessage}</span>
                    </div>
                )}

                {renderContent()}

                <div className="mt-6 pt-4 border-t border-gray-100 dark:border-gray-700 text-center">
                     <button 
                        onClick={onClose}
                        className="text-sm text-gray-500 hover:text-gray-800 dark:text-gray-400 dark:hover:text-gray-200 transition-colors"
                    >
                        取消
                    </button>
                </div>
            </div>
        </div>
    );
};

export default ActionOperationModal;

import React, { useState, useEffect } from 'react';
import { ActionName, OperationType } from '../config';
import { useModalEffects } from '../hooks/useModalEffects';

interface ActionOperationModalProps {
    isOpen: boolean;
    onClose: () => void;
    operationType: OperationType | null;
    currentCounts: Record<ActionName, number>;
    onConfirm: (updates: { action: ActionName; delta: number }[], logDetail?: string) => void;
}

// Section Wrapper Component for visual distinction
const SectionWrapper: React.FC<{ title: string, children: React.ReactNode, borderColor?: string }> = ({ title, children, borderColor }) => (
    <div className="bg-gray-50 dark:bg-slate-700/30 p-4 rounded-xl border border-gray-100 dark:border-slate-700 space-y-3">
        <h4 className={`text-sm font-bold text-gray-800 dark:text-gray-200 border-l-4 ${borderColor || 'border-indigo-500'} pl-2 leading-tight`}>
            {title}
        </h4>
        {children}
    </div>
);

const ActionOperationModal: React.FC<ActionOperationModalProps> = ({ isOpen, onClose, operationType, currentCounts, onConfirm }) => {
    const [errorMessage, setErrorMessage] = useState<string | null>(null);
    useModalEffects(isOpen, onClose, 'action-operation-modal');

    useEffect(() => {
        if (isOpen) {
            setErrorMessage(null);
        }
    }, [isOpen]);

    if (!isOpen || !operationType) return null;

    const getTitle = () => {
        switch (operationType) {
            case 'DELETE': return '執行移除';
            case 'COPY': return '執行複製';
            case 'TRANSFORM': return '執行轉化';
            case 'ADD': return '獲得卡片 / 資源';
            default: return '';
        }
    };

    const getDescription = () => {
        switch (operationType) {
            case 'DELETE': return '選擇要移除的卡片類型。移除起始卡+20pt。移除其他卡片會增加移除次數，並扣除對應卡片的分數（若有）。';
            case 'COPY': return '選擇複製對象。首2張免費，之後每張+40pt (單一角色最多複製4次)。若有神閃會自動+20pt。';
            case 'TRANSFORM': return '轉化視同「移除來源卡片」並「獲得一張中立卡」。請選擇來源卡片類型。';
            case 'ADD': return '新增卡片或特殊計分項目。所有卡片普閃不計分，神閃統一+20pt。';
            default: return '';
        }
    };

    // Helper to generate updates based on selection
    const getUpdates = (category: string): { action: ActionName; delta: number }[] => {

        // --- ADD 獲得 ---
        if (operationType === 'ADD') {
            switch (category) {
                case 'NEUTRAL': return [{ action: '中立卡', delta: 1 }];
                case 'TABOO': return [{ action: '禁忌卡', delta: 1 }];
                case 'REFORGE': return [{ action: '重鑄_神之錘', delta: 1 }];

                case 'MONSTER_NORMAL': return [{ action: '怪物卡_一般', delta: 1 }];
                case 'MONSTER_RARE': return [{ action: '怪物卡_稀有', delta: 1 }];
                case 'MONSTER_LEGEND': return [{ action: '怪物卡_傳說', delta: 1 }];

                case 'GOD_FLASH': return [{ action: '神閃', delta: 1 }];
                default: return [];
            }
        }

        // --- COPY 複製 ---
        if (operationType === 'COPY') {
            const baseCopy = { action: '複製卡片' as ActionName, delta: 1 };
            const godFlash = { action: '神閃' as ActionName, delta: 1 };

            switch (category) {
                // 角色卡
                case 'COPY_CHAR_NORMAL': return [baseCopy];
                case 'COPY_CHAR_GOD': return [baseCopy, godFlash];

                // 中立卡
                case 'COPY_NEUTRAL_NORMAL': return [baseCopy];
                case 'COPY_NEUTRAL_GOD': return [baseCopy, godFlash];

                // 怪物卡
                case 'COPY_MONSTER_NORMAL': return [baseCopy];
                case 'COPY_MONSTER_GOD': return [baseCopy, godFlash];

                default: return [baseCopy];
            }
        }

        // --- DELETE 移除 ---
        if (operationType === 'DELETE') {
            const removeAction = { action: '一般移除' as ActionName, delta: 1 }; // 增加移除次數
            const removeGodFlash = { action: '神閃' as ActionName, delta: -1 }; // 扣除神閃分

            switch (category) {
                // 1. 角色卡
                case 'DEL_CHAR_STARTER': 
                    return [{ action: '移除起始卡', delta: 1 }];
                case 'DEL_CHAR_NORMAL': 
                    // 移除一般角色卡：僅增加移除次數 (角色卡本身無分數計數)
                    return [removeAction];
                case 'DEL_CHAR_GOD': 
                    // 移除神閃角色卡：增加移除次數 + 扣除神閃
                    return [removeAction, removeGodFlash];

                // 2. 中立卡
                case 'DEL_NEUTRAL_NORMAL':
                    // 移除一般中立卡：增加移除次數 + 扣除中立卡數量
                    return [removeAction, { action: '中立卡', delta: -1 }];
                case 'DEL_NEUTRAL_GOD':
                    // 移除神閃中立卡：增加移除次數 + 扣除中立卡數量 + 扣除神閃
                    return [removeAction, { action: '中立卡', delta: -1 }, removeGodFlash];

                // 3. 怪物卡
                case 'DEL_MONSTER_NORMAL':
                    // 移除一般怪物卡：增加移除次數 + 扣除怪物卡數量
                    return [removeAction, { action: '怪物卡_一般', delta: -1 }];
                case 'DEL_MONSTER_GOD':
                    // 移除神閃怪物卡：增加移除次數 + 扣除怪物卡數量 + 扣除神閃
                    return [removeAction, { action: '怪物卡_一般', delta: -1 }, removeGodFlash];

                // 4. 禁忌卡
                case 'DEL_TABOO':
                    // 移除禁忌卡：增加移除次數 + 扣除禁忌卡數量
                    return [removeAction, { action: '禁忌卡', delta: -1 }];

                default: return [];
            }
        }

        // --- TRANSFORM 轉化 ---
        if (operationType === 'TRANSFORM') {
            // 規則8/10: 轉化 = 移除來源 + 獲得新卡 (通常是中立卡)

            const gainNeutral = { action: '中立卡' as ActionName, delta: 1 };

            switch (category) {
                // 來源：起始卡 (+移除起始卡, +中立卡)
                case 'SRC_STARTER': 
                    return [{ action: '移除起始卡', delta: 1 }, gainNeutral];

                // 來源：其他卡 (+一般移除, +中立卡)
                case 'SRC_OTHER': 
                    return [{ action: '一般移除', delta: 1 }, gainNeutral];

                // 來源：複製卡 (-複製卡片, +中立卡) -> 退複製分，加中立分
                case 'SRC_COPY': 
                    return [{ action: '複製卡片', delta: -1 }, gainNeutral];

                default: return [];
            }
        }

        return [];
    };

    const getLogDescription = (category: string): string => {
        switch (operationType) {
            case 'ADD':
                 switch (category) {
                    case 'NEUTRAL': return '獲得中立卡';
                    case 'TABOO': return '獲得禁忌卡';
                    case 'REFORGE': return '重鑄/神之錘';
                    case 'MONSTER_NORMAL': return '獲得怪物卡(一般)';
                    case 'MONSTER_RARE': return '獲得怪物卡(稀有)';
                    case 'MONSTER_LEGEND': return '獲得怪物卡(傳說)';
                    case 'GOD_FLASH': return '獲得神閃';
                    default: return '';
                }
            case 'COPY': 
                switch (category) {
                    case 'COPY_CHAR_NORMAL': return '複製角色卡';
                    case 'COPY_CHAR_GOD': return '複製角色卡(神閃)';
                    case 'COPY_NEUTRAL_NORMAL': return '複製中立卡';
                    case 'COPY_NEUTRAL_GOD': return '複製中立卡(神閃)';
                    case 'COPY_MONSTER_NORMAL': return '複製怪物卡';
                    case 'COPY_MONSTER_GOD': return '複製怪物卡(神閃)';
                    default: return '複製卡片';
                }
            case 'DELETE':
                switch(category) {
                     case 'DEL_CHAR_STARTER': return '移除起始卡';
                     case 'DEL_CHAR_GOD': return '移除角色卡(神閃)';
                     case 'DEL_CHAR_NORMAL': return '移除角色卡(非起始)';
                     case 'DEL_NEUTRAL_NORMAL': return '移除中立卡(一般/普閃)';
                     case 'DEL_NEUTRAL_GOD': return '移除中立卡(神閃)';
                     case 'DEL_MONSTER_NORMAL': return '移除怪物卡(一般/普閃)';
                     case 'DEL_MONSTER_GOD': return '移除怪物卡(神閃)';
                     case 'DEL_TABOO': return '移除禁忌卡';
                     default: return '移除卡片';
                }
             case 'TRANSFORM':
                switch(category) {
                     case 'SRC_STARTER': return '轉化起始卡';
                     case 'SRC_OTHER': return '轉化一般卡';
                     case 'SRC_COPY': return '轉化複製卡';
                     default: return '';
                }
            default: return '';
        }
    };

    const handleSelection = (category: string) => {
        setErrorMessage(null);
        const updates = getUpdates(category);
        const logDetail = getLogDescription(category);

        // Validation Logic: Check for negative results
        const missingItems: string[] = [];
        updates.forEach(({ action, delta }) => {
            if (delta < 0) {
                const currentCount = currentCounts[action] || 0;
                // 注意：一般移除 是增加計數，所以不會在這裡被擋下
                // 但如果是扣除 中立卡/神閃/怪物卡 等持有數，就需要檢查
                if (currentCount + delta < 0) {
                    missingItems.push(action);
                }
            }
        });

        if (missingItems.length > 0) {
            setErrorMessage(`無法執行操作：您的「${missingItems.join('、')}」數量不足。`);
            return;
        }

        onConfirm(updates, logDetail);
        onClose();
    };

    // Style Constants
    const baseBtnClass = "w-full py-3 px-4 rounded-lg border font-semibold text-sm sm:text-base transition-all active:scale-95 shadow-sm flex flex-col items-center justify-center gap-1";

    const blueBtnClass = `${baseBtnClass} bg-blue-50 text-blue-700 border-blue-200 hover:bg-blue-100 dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-800/50 dark:hover:bg-blue-900/30`;
    const greenBtnClass = `${baseBtnClass} bg-emerald-50 text-emerald-700 border-emerald-200 hover:bg-emerald-100 dark:bg-emerald-900/20 dark:text-emerald-300 dark:border-emerald-800/50 dark:hover:bg-emerald-900/30`;
    const purpleBtnClass = `${baseBtnClass} bg-purple-50 text-purple-700 border-purple-200 hover:bg-purple-100 dark:bg-purple-900/20 dark:text-purple-300 dark:border-purple-800/50 dark:hover:bg-purple-900/30`;
    const amberBtnClass = `${baseBtnClass} bg-amber-50 text-amber-700 border-amber-200 hover:bg-amber-100 dark:bg-amber-900/20 dark:text-amber-300 dark:border-amber-800/50 dark:hover:bg-amber-900/30`;
    const redBtnClass = `${baseBtnClass} bg-red-50 text-red-700 border-red-200 hover:bg-red-100 dark:bg-red-900/20 dark:text-red-300 dark:border-red-800/50 dark:hover:bg-red-900/30`;
    const grayBtnClass = `${baseBtnClass} bg-gray-50 text-gray-700 border-gray-200 hover:bg-gray-100 dark:bg-slate-700/40 dark:text-gray-300 dark:border-slate-600 dark:hover:bg-slate-700/60`;

    // --- Content Renderers ---

    const renderAddContent = () => (
        <div className="space-y-4">
            <SectionWrapper title="基礎卡片" borderColor="border-emerald-500">
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('NEUTRAL')} className={greenBtnClass}>
                        <span>中立卡</span>
                        <span className="text-xs opacity-70 font-normal">+20pt</span>
                    </button>
                    <button onClick={() => handleSelection('TABOO')} className={purpleBtnClass}>
                        <span>禁忌卡</span>
                        <span className="text-xs opacity-70 font-normal">+20pt</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="怪物卡" borderColor="border-red-500">
                <div className="grid grid-cols-3 gap-3">
                    <button onClick={() => handleSelection('MONSTER_NORMAL')} className={redBtnClass}>
                        <span>一般</span>
                        <span className="text-xs opacity-70 font-normal">+20pt</span>
                    </button>
                    <button onClick={() => handleSelection('MONSTER_RARE')} className={redBtnClass}>
                        <span>稀有</span>
                        <span className="text-xs opacity-70 font-normal">+50pt</span>
                    </button>
                    <button onClick={() => handleSelection('MONSTER_LEGEND')} className={redBtnClass}>
                        <span>傳說</span>
                        <span className="text-xs opacity-70 font-normal">+80pt</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="特殊" borderColor="border-amber-500">
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('REFORGE')} className={blueBtnClass}>
                        <span>重鑄 / 神之錘</span>
                        <span className="text-xs opacity-70 font-normal">+10pt</span>
                    </button>
                    <button onClick={() => handleSelection('GOD_FLASH')} className={amberBtnClass}>
                        <span>獲得神閃</span>
                        <span className="text-xs opacity-70 font-normal">統一 +20pt</span>
                    </button>
                </div>
                <p className="text-xs text-gray-500 dark:text-gray-400 mt-2 px-1">
                    * 普閃不計分，請勿記錄。神閃適用於任何種類卡片。
                </p>
            </SectionWrapper>
        </div>
    );

    const renderCopyContent = () => (
        <div className="space-y-4">
            <SectionWrapper title="複製角色卡 (Character)" borderColor="border-blue-500">
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('COPY_CHAR_NORMAL')} className={blueBtnClass}>
                        <span>非神閃</span>
                        <span className="text-xs opacity-70 font-normal">複製+1</span>
                    </button>
                    <button onClick={() => handleSelection('COPY_CHAR_GOD')} className={amberBtnClass}>
                        <span>神閃</span>
                        <span className="text-xs opacity-70 font-normal">複製+1 / 神閃+1</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="複製中立卡 (Neutral)" borderColor="border-green-500">
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('COPY_NEUTRAL_NORMAL')} className={blueBtnClass}>
                        <span>非神閃</span>
                        <span className="text-xs opacity-70 font-normal">複製+1</span>
                    </button>
                    <button onClick={() => handleSelection('COPY_NEUTRAL_GOD')} className={amberBtnClass}>
                        <span>神閃</span>
                        <span className="text-xs opacity-70 font-normal">複製+1 / 神閃+1</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="複製怪物卡 (Monster)" borderColor="border-red-500">
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('COPY_MONSTER_NORMAL')} className={blueBtnClass}>
                        <span>非神閃</span>
                        <span className="text-xs opacity-70 font-normal">複製+1</span>
                    </button>
                    <button onClick={() => handleSelection('COPY_MONSTER_GOD')} className={amberBtnClass}>
                        <span>神閃</span>
                        <span className="text-xs opacity-70 font-normal">複製+1 / 神閃+1</span>
                    </button>
                </div>
            </SectionWrapper>
        </div>
    );

    const renderDeleteContent = () => (
        <div className="space-y-4">
            <SectionWrapper title="1. 角色卡 (Character)" borderColor="border-blue-500">
                <div className="grid grid-cols-3 gap-2">
                    <button onClick={() => handleSelection('DEL_CHAR_STARTER')} className={redBtnClass}>
                        <span>起始卡</span>
                        <span className="text-xs opacity-70 font-normal">+20pt</span>
                    </button>
                    <button onClick={() => handleSelection('DEL_CHAR_NORMAL')} className={grayBtnClass}>
                        <span>非起始卡</span>
                        <span className="text-xs opacity-70 font-normal">移除+1</span>
                    </button>
                    <button onClick={() => handleSelection('DEL_CHAR_GOD')} className={amberBtnClass}>
                        <span>神閃</span>
                        <span className="text-xs opacity-70 font-normal">移除+1 / 神閃-1</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="2. 中立卡 (Neutral)" borderColor="border-green-500">
                 <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleSelection('DEL_NEUTRAL_NORMAL')} className={grayBtnClass}>
                        <span>一般 / 普閃</span>
                        <span className="text-xs opacity-70 font-normal">移除+1 / 卡片-1</span>
                    </button>
                    <button onClick={() => handleSelection('DEL_NEUTRAL_GOD')} className={amberBtnClass}>
                        <span>神閃</span>
                        <span className="text-xs opacity-70 font-normal">移除+1 / 神閃-1</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="3. 怪物卡 (Monster)" borderColor="border-red-500">
                <div className="grid grid-cols-2 gap-3">
                     <button onClick={() => handleSelection('DEL_MONSTER_NORMAL')} className={grayBtnClass}>
                        <span>一般 / 普閃</span>
                        <span className="text-xs opacity-70 font-normal">移除+1 / 卡片-1</span>
                    </button>
                    <button onClick={() => handleSelection('DEL_MONSTER_GOD')} className={amberBtnClass}>
                        <span>神閃</span>
                        <span className="text-xs opacity-70 font-normal">移除+1 / 神閃-1</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="4. 其他 (Other)" borderColor="border-gray-500">
                <div className="grid grid-cols-1 gap-3">
                     <button onClick={() => handleSelection('DEL_TABOO')} className={purpleBtnClass}>
                        <span>禁忌卡</span>
                        <span className="text-xs opacity-70 font-normal">移除+1 / 卡片-1</span>
                    </button>
                </div>
            </SectionWrapper>
        </div>
    );

    const renderTransformContent = () => (
        <SectionWrapper title="轉化來源" borderColor="border-purple-500">
            <p className="text-sm text-gray-600 dark:text-gray-400 mb-2">
                轉化 = 移除一張卡 + 獲得一張中立卡。請選擇被轉化(移除)的卡片：
            </p>
            <div className="grid grid-cols-1 gap-3">
                 <button onClick={() => handleSelection('SRC_STARTER')} className={purpleBtnClass}>
                    <span>轉化起始卡</span>
                    <span className="text-xs opacity-70 font-normal">移除起始(+20) + 獲得中立(+20)</span>
                </button>
                <button onClick={() => handleSelection('SRC_OTHER')} className={grayBtnClass}>
                    <span>轉化一般卡</span>
                    <span className="text-xs opacity-70 font-normal">移除一般(+0) + 獲得中立(+20)</span>
                </button>
                <button onClick={() => handleSelection('SRC_COPY')} className={blueBtnClass}>
                    <span>轉化複製卡</span>
                    <span className="text-xs opacity-70 font-normal">退回複製分 + 獲得中立(+20)</span>
                </button>
            </div>
        </SectionWrapper>
    );

    const renderContent = () => {
        switch (operationType) {
            case 'ADD': return renderAddContent();
            case 'COPY': return renderCopyContent();
            case 'DELETE': return renderDeleteContent();
            case 'TRANSFORM': return renderTransformContent();
            default: return null;
        }
    }

    return (
        <div 
            className="fixed inset-0 bg-black bg-opacity-60 dark:bg-opacity-80 flex justify-center items-center z-50 p-4 transition-opacity duration-300"
            onClick={onClose}
        >
            <div 
                id="action-operation-modal"
                className="bg-white dark:bg-slate-800 w-full max-w-md rounded-xl p-6 max-h-[90vh] overflow-y-auto transform transition-all duration-300 ease-out opacity-0 scale-95"
                onClick={(e) => e.stopPropagation()}
            >
                <div className="flex justify-between items-center mb-2">
                    <h3 className="text-xl font-bold text-gray-900 dark:text-gray-100">{getTitle()}</h3>
                    <button onClick={onClose} className="p-2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-200">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                        </svg>
                    </button>
                </div>

                <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">{getDescription()}</p>

                {errorMessage && (
                    <div className="mb-4 p-3 bg-red-100 border border-red-200 text-red-700 rounded-lg text-sm flex items-start animate-pulse">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2 flex-shrink-0" viewBox="0 0 20 20" fill="currentColor">
                            <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                        </svg>
                        <span>{errorMessage}</span>
                    </div>
                )}

                {renderContent()}

                <div className="mt-6 pt-4 border-t border-gray-100 dark:border-gray-700 text-center">
                     <button 
                        onClick={onClose}
                        className="text-sm text-gray-500 hover:text-gray-800 dark:text-gray-400 dark:hover:text-gray-200 transition-colors"
                    >
                        取消
                    </button>
                </div>
            </div>
        </div>
    );
};

export default ActionOperationModal;

import React, { useState, useEffect } from 'react';
import { ActionName, OperationType } from '../config';
import { useModalEffects } from '../hooks/useModalEffects';

interface ActionOperationModalProps {
    isOpen: boolean;
    onClose: () => void;
    operationType: OperationType | null;
    currentCounts: Record<ActionName, number>;
    onConfirm: (updates: { action: ActionName; delta: number }[], logDetail?: string) => void;
}

// Section Wrapper Component for visual distinction
const SectionWrapper: React.FC<{ title: string, children: React.ReactNode, borderColor?: string }> = ({ title, children, borderColor }) => (
    <div className="bg-gray-50 dark:bg-slate-700/30 p-4 rounded-xl border border-gray-100 dark:border-slate-700 space-y-3">
        <h4 className={`text-sm font-bold text-gray-800 dark:text-gray-200 border-l-4 ${borderColor || 'border-indigo-500'} pl-2 leading-tight`}>
            {title}
        </h4>
        {children}
    </div>
);

const ActionOperationModal: React.FC<ActionOperationModalProps> = ({ isOpen, onClose, operationType, currentCounts, onConfirm }) => {
    const [errorMessage, setErrorMessage] = useState<string | null>(null);
    useModalEffects(isOpen, onClose, 'action-operation-modal');

    useEffect(() => {
        if (isOpen) {
            setErrorMessage(null);
        }
    }, [isOpen]);

    if (!isOpen || !operationType) return null;

    const getTitle = () => {
        switch (operationType) {
            case 'DELETE': return '執行移除';
            case 'COPY': return '執行複製';
            case 'TRANSFORM': return '執行轉化';
            case 'ADD': return '獲得卡片 / 資源';
            default: return '';
        }
    };

    const getDescription = () => {
        switch (operationType) {
            case 'DELETE': return '選擇要移除的卡片類型。移除起始卡+20pt。移除其他卡片會增加移除次數，並扣除對應卡片的分數（若有）。';
            case 'COPY': return '選擇複製對象。首2張免費，之後每張+40pt (單一角色最多複製4次)。若有神閃會自動+20pt。';
            case 'TRANSFORM': return '轉化視同「移除來源卡片」並「獲得一張中立卡」。請選擇來源卡片類型。';
            case 'ADD': return '新增卡片或特殊計分項目。所有卡片普閃不計分，神閃統一+20pt。';
            default: return '';
        }
    };

    // Helper to generate updates based on selection
    const getUpdates = (category: string): { action: ActionName; delta: number }[] => {

        // --- ADD 獲得 ---
        if (operationType === 'ADD') {
            switch (category) {
                case 'NEUTRAL': return [{ action: '中立卡', delta: 1 }];
                case 'TABOO': return [{ action: '禁忌卡', delta: 1 }];
                case 'REFORGE': return [{ action: '重鑄_神之錘', delta: 1 }];

                case 'MONSTER_NORMAL': return [{ action: '怪物卡_一般', delta: 1 }];
                case 'MONSTER_RARE': return [{ action: '怪物卡_稀有', delta: 1 }];
                case 'MONSTER_LEGEND': return [{ action: '怪物卡_傳說', delta: 1 }];

                case 'GOD_FLASH': return [{ action: '神閃', delta: 1 }];
                default: return [];
            }
        }

        // --- COPY 複製 ---
        if (operationType === 'COPY') {
            const baseCopy = { action: '複製卡片' as ActionName, delta: 1 };
            const godFlash = { action: '神閃' as ActionName, delta: 1 };

            switch (category) {
                // 角色卡
                case 'COPY_CHAR_NORMAL': return [baseCopy];
                case 'COPY_CHAR_GOD': return [baseCopy, godFlash];

                // 中立卡
                case 'COPY_NEUTRAL_NORMAL': return [baseCopy];
                case 'COPY_NEUTRAL_GOD': return [baseCopy, godFlash];

                // 怪物卡
                case 'COPY_MONSTER_NORMAL': return [baseCopy];
                case 'COPY_MONSTER_GOD': return [baseCopy, godFlash];

                default: return [baseCopy];
            }
        }

        // --- DELETE 移除 ---
        if (operationType === 'DELETE') {
            const removeAction = { action: '一般移除' as ActionName, delta: 1 }; // 增加移除次數
            const removeGodFlash = { action: '神閃' as ActionName, delta: -1 }; // 扣除神閃分

            switch (category) {
                // 1. 角色卡
                case 'DEL_CHAR_STARTER': 
                    return [{ action: '移除起始卡', delta: 1 }];
                case 'DEL_CHAR_NORMAL': 
                    // 移除一般角色卡：僅增加移除次數 (角色卡本身無分數計數)
                    return [removeAction];
                case 'DEL_CHAR_GOD': 
                    // 移除神閃角色卡：增加移除次數 + 扣除神閃
                    return [removeAction, removeGodFlash];

                // 2. 中立卡
                case 'DEL_NEUTRAL_NORMAL':
                    // 移除一般中立卡：增加移除次數 + 扣除中立卡數量
                    return [removeAction, { action: '中立卡', delta: -1 }];
                case 'DEL_NEUTRAL_GOD':
                    // 移除神閃中立卡：增加移除次數 + 扣除中立卡數量 + 扣除神閃
                    return [removeAction, { action: '中立卡', delta: -1 }, removeGodFlash];

                // 3. 怪物卡 (一般)
                case 'DEL_MONSTER_NORMAL':
                    return [removeAction, { action: '怪物卡_一般', delta: -1 }];
                case 'DEL_MONSTER_NORMAL_GOD':
                    return [removeAction, { action: '怪物卡_一般', delta: -1 }, removeGodFlash];

                // 3. 怪物卡 (稀有)
                case 'DEL_MONSTER_RARE':
                    return [removeAction, { action: '怪物卡_稀有', delta: -1 }];
                case 'DEL_MONSTER_RARE_GOD':
                    return [removeAction, { action: '怪物卡_稀有', delta: -1 }, removeGodFlash];

                // 3. 怪物卡 (傳說)
                case 'DEL_MONSTER_LEGEND':
                    return [removeAction, { action: '怪物卡_傳說', delta: -1 }];
                case 'DEL_MONSTER_LEGEND_GOD':
                    return [removeAction, { action: '怪物卡_傳說', delta: -1 }, removeGodFlash];

                // 4. 禁忌卡
                case 'DEL_TABOO':
                    // 移除禁忌卡：增加移除次數 + 扣除禁忌卡數量
                    return [removeAction, { action: '禁忌卡', delta: -1 }];

                default: return [];
            }
        }

        // --- TRANSFORM 轉化 ---
        if (operationType === 'TRANSFORM') {
            // 規則8/10: 轉化 = 移除來源 + 獲得新卡 (通常是中立卡)

            const gainNeutral = { action: '中立卡' as ActionName, delta: 1 };

            switch (category) {
                // 來源：起始卡 (+移除起始卡, +中立卡)
                case 'SRC_STARTER': 
                    return [{ action: '移除起始卡', delta: 1 }, gainNeutral];

                // 來源：其他卡 (+一般移除, +中立卡)
                case 'SRC_OTHER': 
                    return [{ action: '一般移除', delta: 1 }, gainNeutral];

                // 來源：複製卡 (-複製卡片, +中立卡) -> 退複製分，加中立分
                case 'SRC_COPY': 
                    return [{ action: '複製卡片', delta: -1 }, gainNeutral];

                default: return [];
            }
        }

        return [];
    };

    const getLogDescription = (category: string): string => {
        switch (operationType) {
            case 'ADD':
                 switch (category) {
                    case 'NEUTRAL': return '獲得中立卡';
                    case 'TABOO': return '獲得禁忌卡';
                    case 'REFORGE': return '重鑄/神之錘';
                    case 'MONSTER_NORMAL': return '獲得怪物卡(一般)';
                    case 'MONSTER_RARE': return '獲得怪物卡(稀有)';
                    case 'MONSTER_LEGEND': return '獲得怪物卡(傳說)';
                    case 'GOD_FLASH': return '獲得神閃';
                    default: return '';
                }
            case 'COPY': 
                switch (category) {
                    case 'COPY_CHAR_NORMAL': return '複製角色卡';
                    case 'COPY_CHAR_GOD': return '複製角色卡(神閃)';
                    case 'COPY_NEUTRAL_NORMAL': return '複製中立卡';
                    case 'COPY_NEUTRAL_GOD': return '複製中立卡(神閃)';
                    case 'COPY_MONSTER_NORMAL': return '複製怪物卡';
                    case 'COPY_MONSTER_GOD': return '複製怪物卡(神閃)';
                    default: return '複製卡片';
                }
            case 'DELETE':
                switch(category) {
                     case 'DEL_CHAR_STARTER': return '移除起始卡';
                     case 'DEL_CHAR_GOD': return '移除角色卡(神閃)';
                     case 'DEL_CHAR_NORMAL': return '移除角色卡(非起始)';
                     case 'DEL_NEUTRAL_NORMAL': return '移除中立卡(一般/普閃)';
                     case 'DEL_NEUTRAL_GOD': return '移除中立卡(神閃)';

                     case 'DEL_MONSTER_NORMAL': return '移除怪物卡(一般/普閃)';
                     case 'DEL_MONSTER_NORMAL_GOD': return '移除怪物卡(一般/神閃)';
                     case 'DEL_MONSTER_RARE': return '移除怪物卡(稀有/普閃)';
                     case 'DEL_MONSTER_RARE_GOD': return '移除怪物卡(稀有/神閃)';
                     case 'DEL_MONSTER_LEGEND': return '移除怪物卡(傳說/普閃)';
                     case 'DEL_MONSTER_LEGEND_GOD': return '移除怪物卡(傳說/神閃)';

                     case 'DEL_TABOO': return '移除禁忌卡';
                     default: return '移除卡片';
                }
             case 'TRANSFORM':
                switch(category) {
                     case 'SRC_STARTER': return '轉化起始卡';
                     case 'SRC_OTHER': return '轉化一般卡';
                     case 'SRC_COPY': return '轉化複製卡';
                     default: return '';
                }
            default: return '';
        }
    };

    const handleSelection = (category: string) => {
        setErrorMessage(null);
        const updates = getUpdates(category);
        const logDetail = getLogDescription(category);

        // Validation Logic: Check for negative results
        const missingItems: string[] = [];
        updates.forEach(({ action, delta }) => {
            if (delta < 0) {
                const currentCount = currentCounts[action] || 0;
                // 注意：一般移除 是增加計數，所以不會在這裡被擋下
                // 但如果是扣除 中立卡/神閃/怪物卡 等持有數，就需要檢查
                if (currentCount + delta < 0) {
                    missingItems.push(action);
                }
            }
        });

        if (missingItems.length > 0) {
            setErrorMessage(`無法執行操作：您的「${missingItems.join('、')}」數量不足。`);
            return;
        }

        onConfirm(updates, logDetail);
        onClose();
    };

    // Style Constants
    const baseBtnClass = "w-full py-3 px-4 rounded-lg border font-semibold text-sm sm:text-base transition-all active:scale-95 shadow-sm flex flex-col items-center justify-center gap-1";

    const blueBtnClass = `${baseBtnClass} bg-blue-50 text-blue-700 border-blue-200 hover:bg-blue-100 dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-800/50 dark:hover:bg-blue-900/30`;
