                case 'TRF_MONSTER_LEGEND_GOD':
                    return [removeAction, { action: '怪物卡_傳說', delta: -1 }, removeGodFlash, gainNeutral];

                // 4. 禁忌卡
                case 'TRF_TABOO':
                    return [removeAction, { action: '禁忌卡', delta: -1 }, gainNeutral];

                default: return [];
            }
        }

        return [];
    };

