                     case 'TRF_MONSTER_RARE': return '轉化怪物卡(稀有/普閃)';
                     case 'TRF_MONSTER_RARE_GOD': return '轉化怪物卡(稀有/神閃)';
                     case 'TRF_MONSTER_LEGEND': return '轉化怪物卡(傳說/普閃)';
                     case 'TRF_MONSTER_LEGEND_GOD': return '轉化怪物卡(傳說/神閃)';

                     case 'TRF_TABOO': return '轉化禁忌卡';
                     default: return '';
                }
            default: return '';
        }
