    const renderTransformContent = () => (
        <div className="space-y-4">
             <div className="text-sm text-gray-600 dark:text-gray-400 mb-2 p-2 bg-indigo-50 dark:bg-indigo-900/20 rounded border border-indigo-100 dark:border-indigo-800">
