                        <span className="text-xs opacity-70 font-normal">中立(-20) + 中立(+20)</span>
                    </button>
                    <button onClick={() => handleSelection('TRF_NEUTRAL_GOD')} className={amberBtnClass}>
                        <span>神閃</span>
                        <span className="text-xs opacity-70 font-normal">中立(-20) + 神閃(-20) + 中立(+20)</span>
                    </button>
                </div>
            </SectionWrapper>

            <SectionWrapper title="3. 轉化怪物卡" borderColor="border-red-500">
                <div className="grid grid-cols-2 gap-3">
                    {/* 一般 */}
                    <button onClick={() => handleSelection('TRF_MONSTER_NORMAL')} className={grayBtnClass}>
                        <span>一般 / 普閃</span>
                        <span className="text-xs opacity-70 font-normal">一般(-20) + 中立(+20)</span>
                    </button>
                    <button onClick={() => handleSelection('TRF_MONSTER_NORMAL_GOD')} className={amberBtnClass}>
                        <span>一般 / 神閃</span>
                        <span className="text-xs opacity-70 font-normal">一般(-20) + 神閃(-20) + 中立(+20)</span>
                    </button>

                    {/* 稀有 */}
                    <button onClick={() => handleSelection('TRF_MONSTER_RARE')} className={grayBtnClass}>
                        <span>稀有 / 普閃</span>
                        <span className="text-xs opacity-70 font-normal">稀有(-50) + 中立(+20)</span>
                    </button>
                    <button onClick={() => handleSelection('TRF_MONSTER_RARE_GOD')} className={amberBtnClass}>
                        <span>稀有 / 神閃</span>
                        <span className="text-xs opacity-70 font-normal">稀有(-50) + 神閃(-20) + 中立(+20)</span>
                    </button>

                    {/* 傳說 */}
                    <button onClick={() => handleSelection('TRF_MONSTER_LEGEND')} className={grayBtnClass}>
                        <span>傳說 / 普閃</span>
                        <span className="text-xs opacity-70 font-normal">傳說(-80) + 中立(+20)</span>
                    </button>
                    <button onClick={() => handleSelection('TRF_MONSTER_LEGEND_GOD')} className={amberBtnClass}>
                        <span>傳說 / 神閃</span>
                        <span className="text-xs opacity-70 font-normal">傳說(-80) + 神閃(-20) + 中立(+20)</span>
                    </button>
                </div>
            </SectionWrapper>

             <SectionWrapper title="4. 其他" borderColor="border-gray-500">
                <div className="grid grid-cols-1 gap-3">
                     <button onClick={() => handleSelection('TRF_TABOO')} className={purpleBtnClass}>
                        <span>轉化禁忌卡</span>
                        <span className="text-xs opacity-70 font-normal">禁忌(-20) + 中立(+20)</span>
                    </button>
                </div>
            </SectionWrapper>
        </div>
    );

    const renderContent = () => {
        switch (operationType) {
            case 'ADD': return renderAddContent();
            case 'COPY': return renderCopyContent();
            case 'DELETE': return renderDeleteContent();
            case 'TRANSFORM': return renderTransformContent();
            default: return null;
        }
    }

    return (
        <div 
            className="fixed inset-0 bg-black bg-opacity-60 dark:bg-opacity-80 flex justify-center items-center z-50 p-4 transition-opacity duration-300"
            onClick={onClose}
        >
            <div 
                id="action-operation-modal"
                className="bg-white dark:bg-slate-800 w-full max-w-md rounded-xl p-6 max-h-[90vh] overflow-y-auto transform transition-all duration-300 ease-out opacity-0 scale-95"
                onClick={(e) => e.stopPropagation()}
            >
