                                ({removeCount}/{REMOVE_LIMIT})
                            </span>
                        </div>
                        <span className="text-xs opacity-70 font-medium group-hover:opacity-100 transition-opacity">
                            {isDeleteDisabled ? '已達上限' : '起始/一般/複製'}
